INSERT INTO `resep` (`id`, `id_user`, `id_kategori`, `judul`, `deskripsi`, `langkah_memasak`, `jumlah_porsi`, `foto`, `created_at`) VALUES
(207, 3, 2, 'Bakso Ayam Kukus', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Campur daging ayam giling dengan tepung tapioka, bawang putih halus, dan garam.\n2. Tambahkan putih telur dan es batu, uleni hingga kalis.\n3. Bentuk bulat-bulat kecil.\n4. Letakkan di wadah tahan panas yang sudah dioles minyak.\n5. Kukus selama 20-25 menit hingga matang.\n6. Angkat dan sajikan dengan saus sambal atau kuah kaldu.\n7. Bakso ayam kukus siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bakso+Ayam+Kukus', 1, NULL, '2026-07-10 14:14:36'),
(208, 3, 2, 'Bakso Ikan Kuah', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Campur daging ikan giling dengan tepung tapioka, bawang putih, dan garam.\n2. Uleni hingga adonan kalis dan bisa dibentuk.\n3. Didihkan air kaldu ayam untuk kuah.\n4. Bentuk adonan bakso bulat-bulat.\n5. Masukkan bakso ke dalam air mendidih.\n6. Masak hingga bakso mengapung, tandanya sudah matang.\n7. Sajikan dengan kuah, mi, dan taburan bawang goreng.\n8. Bakso ikan kuah siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bakso+Ikan+Kuah', 1, NULL, '2026-07-10 14:14:36'),
(209, 3, 2, 'Bakso Sapi Rebus', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Campur daging sapi giling dengan tepung tapioka, bawang putih halus, dan garam.\n2. Tambahkan es batu sedikit demi sedikit sambil diuleni.\n3. Pastikan adonan kalis dan tidak lengket.\n4. Didihkan air dalam panci besar.\n5. Bentuk adonan bulat-bulat, masukkan ke air mendidih.\n6. Rebus hingga bakso mengapung, angkat.\n7. Sajikan dengan kuah kaldu sapi dan pelengkap.\n8. Bakso sapi rebus siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bakso+Sapi+Rebus', 1, NULL, '2026-07-10 14:14:36'),
(210, 3, 2, 'Bakso Goreng', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Campur daging ayam giling dengan tepung tapioka dan bumbu halus.\n2. Tambahkan daun bawang iris dan sedikit air.\n3. Uleni hingga rata.\n4. Bentuk bulat-bulat kecil.\n5. Panaskan minyak goreng dengan api sedang.\n6. Goreng bakso hingga kuning keemasan.\n7. Angkat dan tiriskan.\n8. Sajikan dengan saus sambal atau mayones.\n\n\nSumber: https://www.google.com/search?q=resep+Bakso+Goreng', 1, NULL, '2026-07-10 14:14:36'),
(211, 3, 2, 'Bakso Keju Goreng', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Campur daging ayam giling dengan tepung tapioka dan bumbu.\n2. Potong keju cheddar kotak kecil untuk isian.\n3. Ambil sedikit adonan, pipihkan, isi dengan keju.\n4. Bentuk bulat hingga keju tertutup rapat.\n5. Panaskan minyak goreng.\n6. Goreng hingga kuning kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan selagi hangat agar keju meleleh.\n\n\nSumber: https://www.google.com/search?q=resep+Bakso+Keju+Goreng', 1, NULL, '2026-07-10 14:14:36'),
(212, 4, 2, 'Nasi Goreng Sayur', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Iris wortel, buncis, dan kol tipis-tipis.\n2. Haluskan bawang merah, bawang putih, dan cabai.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Masukkan sayuran, tumis hingga layu.\n5. Tambahkan nasi putih, aduk rata.\n6. Beri kecap manis, garam, dan merica.\n7. Aduk hingga semua tercampur rata dan nasi panas.\n8. Sajikan dengan telur ceplok dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Goreng+Sayur', 1, NULL, '2026-07-10 14:14:36'),
(213, 4, 2, 'Nasi Goreng Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong dadu daging ayam.\n2. Haluskan bawang merah, bawang putih, dan cabai.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Masukkan ayam, masak hingga berubah warna.\n5. Tambahkan nasi putih, aduk rata.\n6. Beri kecap manis, garam, dan merica.\n7. Aduk hingga nasi panas dan bumbu merata.\n8. Sajikan dengan telur ceplok dan acar.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Goreng+Ayam', 1, NULL, '2026-07-10 14:14:36'),
(214, 4, 2, 'Nasi Goreng Sapi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong kecil daging sapi.\n2. Haluskan bawang merah, bawang putih, dan cabai.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Masukkan daging sapi, masak hingga matang.\n5. Tambahkan nasi putih, aduk rata.\n6. Beri kecap manis, garam, dan merica.\n7. Aduk hingga merata dan nasi panas.\n8. Sajikan dengan taburan bawang goreng.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Goreng+Sapi', 1, NULL, '2026-07-10 14:14:36'),
(215, 4, 2, 'Nasi Goreng Pete', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Kupas dan belah pete menjadi dua bagian.\n2. Haluskan bawang merah, bawang putih, dan cabai.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Masukkan pete, tumis sebentar.\n5. Tambahkan nasi putih, aduk rata.\n6. Beri kecap manis, garam, dan merica.\n7. Aduk hingga tercampur rata dan nasi panas.\n8. Sajikan dengan kerupuk dan telur dadar.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Goreng+Pete', 1, NULL, '2026-07-10 14:14:36'),
(216, 4, 2, 'Nasi Goreng Kambing', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong dadu daging kambing.\n2. Haluskan bawang merah, bawang putih, dan cabai.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Masukkan daging kambing, masak hingga empuk.\n5. Tambahkan nasi putih, aduk rata.\n6. Beri kecap manis, garam, dan merica.\n7. Aduk hingga merata dan nasi panas.\n8. Sajikan dengan acar timun dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Goreng+Kambing', 1, NULL, '2026-07-10 14:14:37'),
(217, 5, 2, 'Sate Ayam Bumbu Kacang', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging ayam dadu kecil.\n2. Campur dengan kecap manis, bawang putih halus, dan ketumbar.\n3. Marinasi selama 30 menit.\n4. Tusuk daging ayam ke tusukan sate.\n5. Bakar sate di atas bara api sambil dibolak-balik.\n6. Haluskan kacang tanah goreng dengan cabai dan bawang.\n7. Sajikan sate dengan bumbu kacang dan kecap manis.\n8. Sate ayam bumbu kacang siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Sate+Ayam+Bumbu+Kacang', 1, NULL, '2026-07-10 14:14:37'),
(218, 5, 2, 'Sate Lilit Ikan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Campur daging ikan giling dengan kelapa parut dan bumbu halus.\n2. Tambahkan daun jeruk iris dan garam.\n3. Ambil adonan, lilitkan pada tusukan sate atau batang serai.\n4. Panggang di atas bara api hingga matang.\n5. Bakar sambil sesekali dibalik agar matang merata.\n6. Angkat ketika sudah kecoklatan.\n7. Sajikan dengan sambal matah.\n8. Sate lilit ikan khas Bali siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Sate+Lilit+Ikan', 1, NULL, '2026-07-10 14:14:37'),
(219, 5, 2, 'Sate Sapi Madura', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging sapi tipis melebar.\n2. Campur dengan kecap manis, bawang putih, dan ketumbar.\n3. Marinasi minimal 30 menit.\n4. Tusuk daging pada tusukan sate.\n5. Bakar di atas bara api hingga matang.\n6. Sajikan dengan bumbu kacang yang dicampur kecap.\n7. Taburi bawang goreng dan irisan cabai.\n8. Sate sapi Madura siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Sate+Sapi+Madura', 1, NULL, '2026-07-10 14:14:37'),
(220, 5, 2, 'Sate Kambing', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging kambing dadu kecil.\n2. Campur dengan kecap manis, jahe parut, dan bawang putih.\n3. Marinasi selama 1 jam agar empuk.\n4. Tusuk daging ke tusukan sate.\n5. Bakar di atas bara api hingga matang.\n6. Balik sesekali agar tidak gosong.\n7. Sajikan dengan kecap manis, irisan cabai, dan bawang merah.\n8. Sate kambing siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Sate+Kambing', 1, NULL, '2026-07-10 14:14:37'),
(221, 5, 2, 'Sate Kulit Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Cuci bersih kulit ayam, potong kotak.\n2. Campur dengan kecap manis, bawang putih, dan merica.\n3. Marinasi 15 menit.\n4. Tusuk kulit ayam pada tusukan sate.\n5. Bakar di atas bara api hingga mengeluarkan minyak.\n6. Panggang hingga kecokelatan.\n7. Sajikan dengan sambal kecap.\n8. Sate kulit ayam siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Sate+Kulit+Ayam', 1, NULL, '2026-07-10 14:14:37'),
(222, 6, 6, 'Soto Ayam Bening', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus ayam dengan air, bawang putih, jahe, dan garam.\n2. Angkat ayam, suwir-suwir dagingnya.\n3. Saring kaldu untuk kuah bening.\n4. Tumis bumbu halus (bawang merah, bawang putih, kunyit).\n5. Masukkan tumisan ke dalam kaldu.\n6. Sajikan dengan suwiran ayam, bihun, dan telur rebus.\n7. Taburi bawang goreng dan seledri.\n8. Soto ayam bening siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Soto+Ayam+Bening', 1, NULL, '2026-07-10 14:14:37'),
(223, 6, 6, 'Soto Ayam Kuning', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Haluskan bawang merah, bawang putih, kunyit, jahe, dan kemiri.\n2. Tumis bumbu halus hingga harum.\n3. Rebus ayam dengan air dan bumbu tumis.\n4. Angkat ayam, goreng sebentar, suwir-suwir.\n5. Tambahkan santan ke dalam kuah, aduk rata.\n6. Sajikan dengan suwiran ayam, kol iris, dan toge.\n7. Tambahkan sambal dan kecap manis.\n8. Soto ayam kuning siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Soto+Ayam+Kuning', 1, NULL, '2026-07-10 14:14:37'),
(224, 6, 6, 'Soto Betawi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus daging sapi hingga empuk, potong dadu.\n2. Tumis bumbu halus (bawang merah, bawang putih, kunyit, jahe).\n3. Masukkan tumisan ke dalam kaldu sapi.\n4. Tambahkan santan dan susu, aduk rata.\n5. Beri garam, merica, dan gula pasir.\n6. Sajikan dengan potongan daging, tomat, dan daun bawang.\n7. Tambahkan emping dan sambal.\n8. Soto Betawi siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Soto+Betawi', 1, NULL, '2026-07-10 14:14:37'),
(225, 6, 6, 'Soto Banjar', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus ayam dengan air hingga empuk.\n2. Tumis bumbu halus (bawang merah, bawang putih, jahe, pala).\n3. Masukkan bumbu ke dalam rebusan ayam.\n4. Tambahkan kayu manis dan cengkeh.\n5. Angkat ayam, suwir-suwir.\n6. Sajikan kuah dengan suwiran ayam, perkedel, dan ketupat.\n7. Tambahkan telur rebus dan bawang goreng.\n8. Soto Banjar siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Soto+Banjar', 1, NULL, '2026-07-10 14:14:37'),
(226, 6, 6, 'Soto Medan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus ayam dengan air hingga empuk.\n2. Tumis bumbu halus (bawang merah, bawang putih, kunyit, lengkuas).\n3. Masukkan tumisan ke dalam rebusan ayam.\n4. Tambahkan santan kental, aduk rata.\n5. Beri garam dan merica.\n6. Sajikan dengan suwiran ayam, toge, dan telur rebus.\n7. Tambahkan emping dan sambal bajak.\n8. Soto Medan siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Soto+Medan', 1, NULL, '2026-07-10 14:14:37'),
(227, 7, 2, 'Mie Goreng Sayur', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus mie hingga matang, tiriskan.\n2. Iris wortel, kol, dan sawi hijau.\n3. Haluskan bawang merah, bawang putih, dan cabai.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan sayuran, tumis hingga layu.\n6. Tambahkan mie, kecap manis, garam, dan merica.\n7. Aduk rata hingga mie panas.\n8. Sajikan dengan acar dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Mie+Goreng+Sayur', 1, NULL, '2026-07-10 14:14:37'),
(228, 7, 2, 'Mie Goreng Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus mie hingga matang, tiriskan.\n2. Potong dadu daging ayam.\n3. Haluskan bawang merah, bawang putih, dan cabai.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan ayam, masak hingga berubah warna.\n6. Tambahkan mie, kecap manis, garam, dan merica.\n7. Aduk rata hingga mie panas.\n8. Sajikan dengan acar dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Mie+Goreng+Ayam', 1, NULL, '2026-07-10 14:14:37'),
(229, 7, 2, 'Mie Goreng Seafood', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus mie hingga matang, tiriskan.\n2. Bersihkan udang, cumi, dan bakso ikan.\n3. Haluskan bawang merah, bawang putih, dan cabai.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan seafood, masak hingga matang.\n6. Tambahkan mie, kecap manis, garam, dan merica.\n7. Aduk rata hingga mie panas.\n8. Sajikan dengan jeruk nipis dan acar.\n\n\nSumber: https://www.google.com/search?q=resep+Mie+Goreng+Seafood', 1, NULL, '2026-07-10 14:14:37'),
(230, 7, 2, 'Mie Goreng Sapi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus mie hingga matang, tiriskan.\n2. Iris tipis daging sapi.\n3. Haluskan bawang merah, bawang putih, dan cabai.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan daging sapi, masak hingga matang.\n6. Tambahkan mie, kecap manis, garam, dan merica.\n7. Aduk rata hingga mie panas.\n8. Sajikan dengan acar timun dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Mie+Goreng+Sapi', 1, NULL, '2026-07-10 14:14:37'),
(231, 7, 2, 'Mie Goreng Kari', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus mie hingga matang, tiriskan.\n2. Haluskan bawang merah, bawang putih, kunyit, dan ketumbar.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan udang dan bakso, masak sebentar.\n5. Tambahkan mie, bubuk kari, garam, dan merica.\n6. Aduk rata hingga mie panas.\n7. Tambahkan potongan cabai merah.\n8. Sajikan dengan acar dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Mie+Goreng+Kari', 1, NULL, '2026-07-10 14:14:37'),
(232, 3, 2, 'Gado-gado Tahu', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong tahu kotak, goreng hingga kecoklatan.\n2. Rebus bayam, toge, dan kacang panjang sebentar.\n3. Potong timun dan kol.\n4. Haluskan kacang tanah goreng dengan cabai dan bawang putih.\n5. Campur bumbu kacang dengan air hangat dan kecap manis.\n6. Tata sayuran dan tahu di piring.\n7. Siram dengan bumbu kacang.\n8. Taburi bawang goreng dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Gado-gado+Tahu', 1, NULL, '2026-07-10 14:14:37'),
(233, 3, 2, 'Gado-gado Tempe', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong tempe kotak, goreng hingga kecoklatan.\n2. Rebus bayam, toge, dan kacang panjang sebentar.\n3. Potong timun dan kol.\n4. Haluskan kacang tanah goreng dengan cabai dan bawang putih.\n5. Campur bumbu kacang dengan air hangat dan kecap manis.\n6. Tata sayuran dan tempe di piring.\n7. Siram dengan bumbu kacang.\n8. Sajikan dengan kerupuk dan lontong.\n\n\nSumber: https://www.google.com/search?q=resep+Gado-gado+Tempe', 1, NULL, '2026-07-10 14:14:37'),
(234, 3, 2, 'Gado-gado Telur', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus telur hingga matang, kupas, belah dua.\n2. Rebus bayam, toge, dan kacang panjang sebentar.\n3. Potong timun dan kol.\n4. Haluskan kacang tanah goreng dengan cabai dan bawang putih.\n5. Campur bumbu kacang dengan air hangat.\n6. Tata sayuran dan telur di piring.\n7. Siram dengan bumbu kacang.\n8. Taburi bawang goreng dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Gado-gado+Telur', 1, NULL, '2026-07-10 14:14:37'),
(235, 3, 2, 'Gado-gado Komplit', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus telur, kupas, belah dua.\n2. Goreng tahu dan tempe hingga kecoklatan.\n3. Rebus bayam, toge, kacang panjang, dan kentang.\n4. Potong timun dan kol.\n5. Haluskan kacang tanah goreng dengan bumbu.\n6. Tata semua bahan di piring besar.\n7. Siram dengan bumbu kacang.\n8. Taburi bawang goreng dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Gado-gado+Komplit', 1, NULL, '2026-07-10 14:14:37'),
(236, 3, 2, 'Gado-gado Goreng', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Goreng tahu dan tempe hingga kecoklatan.\n2. Goreng kentang yang sudah diiris tipis.\n3. Rebus bayam dan toge sebentar.\n4. Haluskan kacang tanah goreng dengan cabai dan bawang.\n5. Campur bumbu kacang dengan air hangat.\n6. Campur semua bahan goreng dan rebus.\n7. Siram dengan bumbu kacang.\n8. Sajikan dengan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Gado-gado+Goreng', 1, NULL, '2026-07-10 14:14:37'),
(237, 4, 2, 'Rendang Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe, dan lengkuas.\n3. Tumis bumbu halus dengan serai dan daun jeruk.\n4. Masukkan santan, aduk rata.\n5. Tambahkan ayam, masak dengan api kecil.\n6. Aduk sesekali hingga kuah menyusut dan mengental.\n7. Masak terus hingga bumbu meresap dan ayam empuk.\n8. Rendang ayam siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rendang+Ayam', 1, NULL, '2026-07-10 14:14:37'),
(238, 4, 2, 'Rendang Sapi Tanpa Santan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging sapi ukuran besar.\n2. Haluskan bawang merah, bawang putih, cabai, dan rempah.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan daging sapi, aduk rata.\n5. Tambahkan air secukupnya.\n6. Masak dengan api kecil hingga daging empuk.\n7. Beri garam dan penyedap alami.\n8. Masak hingga kuah habis dan bumbu meresap.\n\n\nSumber: https://www.google.com/search?q=resep+Rendang+Sapi+Tanpa+Santan', 1, NULL, '2026-07-10 14:14:37'),
(239, 4, 2, 'Rendang Sapi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging sapi ukuran besar.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe, lengkuas.\n3. Tumis bumbu halus dengan serai, daun jeruk, dan daun kunyit.\n4. Masukkan santan kental, aduk rata.\n5. Tambahkan daging sapi.\n6. Masak dengan api kecil sambil sesekali diaduk.\n7. Masak hingga kuah mengental dan daging empuk.\n8. Rendang sapi siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rendang+Sapi', 1, NULL, '2026-07-10 14:14:37'),
(240, 4, 2, 'Rendang Padang', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging sapi ukuran besar.\n2. Haluskan bawang merah, bawang putih, cabai keriting, kunyit, jahe, lengkuas.\n3. Tumis bumbu halus dengan serai, daun jeruk, dan daun kunyit.\n4. Masukkan santan kelapa, aduk hingga mendidih.\n5. Masukkan daging sapi, kecilkan api.\n6. Masak selama 3-4 jam sambil sesekali diaduk.\n7. Masak hingga kuah mengering dan berwarna gelap.\n8. Rendang Padang siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rendang+Padang', 1, NULL, '2026-07-10 14:14:37'),
(241, 4, 2, 'Rendang Jeroan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan jeroan sapi, rebus hingga empuk, potong kecil.\n2. Haluskan bawang merah, bawang putih, cabai, dan rempah.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan jeroan, aduk rata.\n5. Tambahkan santan, masak dengan api kecil.\n6. Aduk sesekali hingga kuah menyusut.\n7. Beri garam dan gula merah.\n8. Rendang jeroan siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rendang+Jeroan', 1, NULL, '2026-07-10 14:14:37'),
(242, 5, 2, 'Ayam Goreng Tanpa Kulit', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Buang kulit ayam, cuci bersih.\n2. Haluskan bawang putih, kunyit, jahe, dan garam.\n3. Lumuri ayam dengan bumbu halus.\n4. Diamkan selama 15 menit.\n5. Panaskan minyak goreng.\n6. Goreng ayam dengan api sedang hingga matang.\n7. Balik agar matang merata.\n8. Angkat dan tiriskan, sajikan hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Ayam+Goreng+Tanpa+Kulit', 1, NULL, '2026-07-10 14:14:37'),
(243, 5, 2, 'Ayam Goreng Tepung', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam menjadi beberapa bagian.\n2. Campur tepung terigu, tepung maizena, garam, dan merica.\n3. Kocok telur dengan sedikit garam.\n4. Celupkan ayam ke telur, lalu gulingkan di tepung.\n5. Remas-remas agar tepung menempel.\n6. Panaskan minyak goreng.\n7. Goreng ayam hingga kuning kecoklatan.\n8. Angkat dan tiriskan, sajikan dengan saus.\n\n\nSumber: https://www.google.com/search?q=resep+Ayam+Goreng+Tepung', 1, NULL, '2026-07-10 14:14:38'),
(244, 5, 2, 'Ayam Goreng Mentega', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam bagian dada, lumuri garam dan merica.\n2. Goreng ayam hingga setengah matang, tiriskan.\n3. Lelehkan mentega, tumis bawang putih cincang.\n4. Masukkan kecap manis dan saus tiram.\n5. Tambahkan sedikit air dan ayam.\n6. Aduk rata, masak hingga bumbu meresap.\n7. Tambahkan daun bawang iris.\n8. Ayam goreng mentega siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Ayam+Goreng+Mentega', 1, NULL, '2026-07-10 14:14:38'),
(245, 5, 2, 'Ayam Goreng Kremes', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus ayam dengan bumbu halus hingga empuk.\n2. Angkat ayam, tiriskan.\n3. Goreng ayam hingga kecoklatan.\n4. Campur sisa kaldu dengan tepung sagu dan telur.\n5. Goreng adonan kremes dengan cara mencipratkan ke minyak panas.\n6. Angkat kremes ketika sudah kuning.\n7. Sajikan ayam dengan taburan kremes.\n8. Ayam goreng kremes siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Ayam+Goreng+Kremes', 1, NULL, '2026-07-10 14:14:38'),
(246, 5, 2, 'Ayam Goreng Crispy', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam kecil-kecil.\n2. Campur tepung terigu, maizena, baking powder, garam, dan merica.\n3. Celupkan ayam ke dalam air es.\n4. Gulingkan ke campuran tepung.\n5. Remas hingga terbentuk lapisan keriting.\n6. Panaskan minyak banyak.\n7. Goreng ayam hingga kuning kecoklatan.\n8. Angkat dan tiriskan, sajikan dengan saus sambal.\n\n\nSumber: https://www.google.com/search?q=resep+Ayam+Goreng+Crispy', 1, NULL, '2026-07-10 14:14:38'),
(247, 6, 2, 'Ikan Bakar Bumbu Kuning', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan, kerat kedua sisinya.\n2. Haluskan bawang merah, bawang putih, kunyit, jahe, dan ketumbar.\n3. Lumuri ikan dengan bumbu halus dan garam.\n4. Diamkan 30 menit.\n5. Bakar ikan di atas bara api.\n6. Olesi sisa bumbu saat membakar.\n7. Balik ikan agar matang merata.\n8. Sajikan dengan sambal dan lalapan.\n\n\nSumber: https://www.google.com/search?q=resep+Ikan+Bakar+Bumbu+Kuning', 1, NULL, '2026-07-10 14:14:38'),
(248, 6, 2, 'Ikan Bakar Kecap', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan, kerat kedua sisinya.\n2. Campur kecap manis, bawang putih cincang, jahe, dan merica.\n3. Lumuri ikan dengan bumbu kecap.\n4. Diamkan 15 menit.\n5. Bakar ikan di atas bara api.\n6. Olesi sisa bumbu kecap saat membakar.\n7. Balik ikan, bakar hingga matang.\n8. Sajikan dengan sambal kecap dan jeruk nipis.\n\n\nSumber: https://www.google.com/search?q=resep+Ikan+Bakar+Kecap', 1, NULL, '2026-07-10 14:14:38'),
(249, 6, 2, 'Ikan Bakar Padang', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan, kerat kedua sisinya.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe.\n3. Lumuri ikan dengan bumbu halus dan air jeruk nipis.\n4. Diamkan 30 menit.\n5. Bakar ikan di atas bara api.\n6. Sajikan dengan sambal hijau khas Padang.\n7. Tambahkan lalapan segar.\n8. Ikan bakar Padang siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Ikan+Bakar+Padang', 1, NULL, '2026-07-10 14:14:38'),
(250, 6, 2, 'Ikan Bakar Jimbaran', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan, kerat kedua sisinya.\n2. Haluskan bawang merah, bawang putih, cabai, terasi, dan gula merah.\n3. Lumuri ikan dengan bumbu halus.\n4. Diamkan 30 menit.\n5. Bakar ikan di atas bara api.\n6. Olesi sisa bumbu saat membakar.\n7. Balik ikan hingga matang sempurna.\n8. Sajikan dengan sambal matah dan nasi hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Ikan+Bakar+Jimbaran', 1, NULL, '2026-07-10 14:14:38'),
(251, 6, 2, 'Ikan Bakar Sambal Matah', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan, lumuri garam dan jeruk nipis.\n2. Bakar ikan di atas bara api hingga matang.\n3. Iris tipis bawang merah, cabai, serai, dan daun jeruk.\n4. Campur irisan dengan minyak kelapa dan perasan jeruk.\n5. Tambahkan garam dan gula.\n6. Aduk rata sambal matah.\n7. Siram sambal matah di atas ikan bakar.\n8. Sajikan dengan nasi hangat dan lalapan.\n\n\nSumber: https://www.google.com/search?q=resep+Ikan+Bakar+Sambal+Matah', 1, NULL, '2026-07-10 14:14:38'),
(252, 7, 2, 'Nasi Uduk Telur', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Cuci beras hingga bersih.\n2. Rebus santan dengan serai, daun salam, dan garam.\n3. Masukkan beras, masak hingga air terserap.\n4. Kukus nasi hingga matang sempurna.\n5. Goreng telur dadar, iris tipis.\n6. Sajikan nasi uduk dengan telur dadar.\n7. Taburi bawang goreng dan timun iris.\n8. Nasi uduk telur siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Uduk+Telur', 1, NULL, '2026-07-10 14:14:38'),
(253, 7, 2, 'Nasi Uduk Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Cuci beras, masak dengan santan berbumbu.\n2. Kukus hingga matang.\n3. Goreng ayam yang sudah dibumbui kuning.\n4. Suwir-suwir daging ayam.\n5. Sajikan nasi uduk dengan suwiran ayam.\n6. Tambahkan telur dadar iris dan timun.\n7. Taburi bawang goreng dan sambal.\n8. Nasi uduk ayam siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Uduk+Ayam', 1, NULL, '2026-07-10 14:14:38'),
(254, 7, 2, 'Nasi Uduk Semur', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Cuci beras, masak dengan santan berbumbu.\n2. Kukus hingga matang.\n3. Rebus daging sapi untuk semur hingga empuk.\n4. Tumis bawang merah, bawang putih, pala, dan cengkeh.\n5. Masukkan daging, kecap manis, dan air.\n6. Masak hingga kuah mengental.\n7. Sajikan nasi uduk dengan semur daging.\n8. Taburi bawang goreng.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Uduk+Semur', 1, NULL, '2026-07-10 14:14:38'),
(255, 7, 2, 'Nasi Uduk Komplit', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Cuci beras, masak dengan santan berbumbu.\n2. Kukus hingga matang.\n3. Goreng ayam berbumbu kuning, suwir.\n4. Goreng tempe dan tahu.\n5. Buat sambal goreng kentang.\n6. Sajikan nasi uduk dengan semua lauk.\n7. Tambahkan telur dadar dan timun.\n8. Taburi bawang goreng dan kerupuk.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Uduk+Komplit', 1, NULL, '2026-07-10 14:14:38'),
(256, 7, 2, 'Nasi Uduk Goreng', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Cuci beras, masak dengan santan berbumbu, kukus.\n2. Diamkan nasi uduk hingga dingin.\n3. Panaskan minyak, tumis bawang putih dan cabai.\n4. Masukkan nasi uduk, aduk rata.\n5. Beri kecap manis dan garam.\n6. Aduk hingga panas merata.\n7. Tambahkan telur dadar iris.\n8. Sajikan dengan acar dan bawang goreng.\n\n\nSumber: https://www.google.com/search?q=resep+Nasi+Uduk+Goreng', 1, NULL, '2026-07-10 14:14:38'),
(257, 3, 2, 'Gulai Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe, lengkuas.\n3. Tumis bumbu halus dengan serai, daun salam, dan daun jeruk.\n4. Masukkan santan, aduk rata.\n5. Tambahkan ayam, masak dengan api sedang.\n6. Beri garam dan gula.\n7. Masak hingga ayam empuk dan kuah mengental.\n8. Gulai ayam siap dinikmati dengan nasi hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Gulai+Ayam', 1, NULL, '2026-07-10 14:14:38'),
(258, 3, 2, 'Gulai Ikan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan, potong sesuai selera.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe.\n3. Tumis bumbu halus dengan serai dan daun salam.\n4. Masukkan santan, aduk rata.\n5. Tambahkan ikan, masak dengan api kecil.\n6. Beri garam dan asam jawa.\n7. Masak hingga ikan matang dan kuah mengental.\n8. Gulai ikan siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Gulai+Ikan', 1, NULL, '2026-07-10 14:14:38'),
(259, 3, 2, 'Gulai Kambing', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging kambing ukuran kecil.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe, lengkuas.\n3. Tumis bumbu halus dengan serai dan daun kari.\n4. Masukkan daging kambing, aduk rata.\n5. Tambahkan santan, masak dengan api kecil.\n6. Beri garam dan gula.\n7. Masak hingga daging empuk dan kuah mengental.\n8. Gulai kambing siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Gulai+Kambing', 1, NULL, '2026-07-10 14:14:38'),
(260, 3, 2, 'Gulai Cumi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan cumi, potong cincin.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe.\n3. Tumis bumbu halus dengan serai dan daun jeruk.\n4. Masukkan santan, aduk rata.\n5. Tambahkan cumi, masak sebentar.\n6. Beri garam dan gula.\n7. Masak hingga cumi matang (jangan terlalu lama agar tidak alot).\n8. Gulai cumi siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Gulai+Cumi', 1, NULL, '2026-07-10 14:14:38'),
(261, 3, 2, 'Gulai Babat', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan babat sapi, rebus hingga empuk, potong kecil.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe, lengkuas.\n3. Tumis bumbu halus dengan serai dan daun salam.\n4. Masukkan santan, aduk rata.\n5. Tambahkan babat, masak dengan api kecil.\n6. Beri garam dan gula.\n7. Masak hingga kuah mengental dan meresap.\n8. Gulai babat siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Gulai+Babat', 1, NULL, '2026-07-10 14:14:38'),
(262, 4, 2, 'Opor Ayam Tanpa Santan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, kemiri, ketumbar, kunyit.\n3. Tumis bumbu halus dengan serai, daun salam, dan lengkuas.\n4. Masukkan ayam, aduk rata.\n5. Tambahkan air, garam, dan gula.\n6. Masak dengan api sedang hingga ayam empuk.\n7. Koreksi rasa, angkat.\n8. Opor ayam tanpa santan siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Opor+Ayam+Tanpa+Santan', 1, NULL, '2026-07-10 14:14:38'),
(263, 4, 2, 'Opor Ayam Putih', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, kemiri, ketumbar, jahe.\n3. Tumis bumbu halus dengan serai, daun salam, dan lengkuas.\n4. Masukkan ayam, aduk hingga berubah warna.\n5. Tambahkan santan, garam, dan gula.\n6. Masak dengan api kecil hingga ayam empuk.\n7. Aduk sesekali agar santan tidak pecah.\n8. Opor ayam putih siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Opor+Ayam+Putih', 1, NULL, '2026-07-10 14:14:38'),
(264, 4, 2, 'Opor Ayam Kuning', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, kemiri, kunyit, ketumbar.\n3. Tumis bumbu halus dengan serai, daun salam, dan lengkuas.\n4. Masukkan ayam, aduk rata.\n5. Tambahkan santan, garam, dan gula.\n6. Masak dengan api kecil hingga ayam empuk.\n7. Aduk sesekali agar santan tidak pecah.\n8. Opor ayam kuning siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Opor+Ayam+Kuning', 1, NULL, '2026-07-10 14:14:38'),
(265, 4, 2, 'Opor Ayam Kampung', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam kampung menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, kemiri, kunyit, jahe.\n3. Tumis bumbu halus dengan serai dan daun salam.\n4. Masukkan ayam kampung, aduk rata.\n5. Tambahkan santan dan air, garam, gula.\n6. Masak dengan api kecil hingga ayam empuk (lebih lama).\n7. Aduk sesekali.\n8. Opor ayam kampung siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Opor+Ayam+Kampung', 1, NULL, '2026-07-10 14:14:38'),
(266, 4, 2, 'Opor Ayam Kremesan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam, rebus dengan bumbu opor hingga empuk.\n2. Angkat ayam, goreng sebentar.\n3. Sisa kuah opor dicampur tepung beras dan telur.\n4. Goreng adonan kremes dalam minyak panas.\n5. Sajikan ayam opor dengan taburan kremes.\n6. Siram dengan kuah opor.\n7. Taburi bawang goreng.\n8. Opor ayam kremesan siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Opor+Ayam+Kremesan', 1, NULL, '2026-07-10 14:14:38'),
(267, 5, 6, 'Rawon Daging Sapi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging sapi ukuran sedang.\n2. Haluskan bawang merah, bawang putih, kluwek, jahe, kunyit, ketumbar.\n3. Tumis bumbu halus dengan serai, daun jeruk, dan lengkuas.\n4. Masukkan daging sapi, aduk rata.\n5. Tambahkan air, masak hingga daging empuk.\n6. Beri garam dan gula.\n7. Masak hingga kuah berwarna hitam pekat.\n8. Sajikan dengan telur asin, tauge, dan sambal terasi.\n\n\nSumber: https://www.google.com/search?q=resep+Rawon+Daging+Sapi', 1, NULL, '2026-07-10 14:14:38'),
(268, 5, 6, 'Rawon Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ayam menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, kluwek, jahe, kunyit.\n3. Tumis bumbu halus dengan serai dan daun jeruk.\n4. Masukkan ayam, aduk rata.\n5. Tambahkan air, masak hingga ayam empuk.\n6. Beri garam dan gula.\n7. Masak hingga kuah berwarna gelap.\n8. Sajikan dengan nasi hangat dan tauge.\n\n\nSumber: https://www.google.com/search?q=resep+Rawon+Ayam', 1, NULL, '2026-07-10 14:14:38'),
(269, 5, 6, 'Rawon Gajebo', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong daging sapi (gajebo/sandung lamur) ukuran besar.\n2. Haluskan bawang merah, bawang putih, kluwek, jahe, kunyit.\n3. Tumis bumbu halus dengan serai dan daun jeruk.\n4. Masukkan daging, aduk rata.\n5. Tambahkan air, masak hingga daging empuk.\n6. Beri garam dan gula merah.\n7. Masak hingga kuah mengental dan gelap.\n8. Sajikan dengan nasi hangat dan sambal.\n\n\nSumber: https://www.google.com/search?q=resep+Rawon+Gajebo', 1, NULL, '2026-07-10 14:14:38'),
(270, 5, 6, 'Rawon Iga', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus iga sapi hingga empuk.\n2. Haluskan bawang merah, bawang putih, kluwek, jahe, kunyit.\n3. Tumis bumbu halus dengan serai dan daun jeruk.\n4. Masukkan iga dan air kaldu.\n5. Beri garam dan gula.\n6. Masak hingga kuah berwarna hitam pekat.\n7. Koreksi rasa.\n8. Sajikan dengan tauge dan telur asin.\n\n\nSumber: https://www.google.com/search?q=resep+Rawon+Iga', 1, NULL, '2026-07-10 14:14:38'),
(271, 5, 6, 'Rawon Babat', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan babat, rebus hingga empuk, potong kecil.\n2. Haluskan bawang merah, bawang putih, kluwek, jahe, kunyit.\n3. Tumis bumbu halus dengan serai dan daun jeruk.\n4. Masukkan babat, aduk rata.\n5. Tambahkan air kaldu, garam, dan gula.\n6. Masak hingga kuah gelap dan meresap.\n7. Koreksi rasa.\n8. Sajikan dengan nasi hangat dan sambal.\n\n\nSumber: https://www.google.com/search?q=resep+Rawon+Babat', 1, NULL, '2026-07-10 14:14:39'),
(272, 6, 6, 'Sop Iga Bening', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus iga sapi hingga empuk, buang lemak.\n2. Iris wortel dan kentang dadu.\n3. Masukkan sayuran ke dalam rebusan iga.\n4. Tambahkan bawang putih, garam, dan merica.\n5. Masak hingga sayuran matang.\n6. Taburi daun bawang dan seledri.\n7. Sajikan hangat dengan sambal dan emping.\n8. Sop iga bening siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Sop+Iga+Bening', 1, NULL, '2026-07-10 14:14:39'),
(273, 6, 6, 'Sop Iga Sapi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus iga sapi hingga empuk.\n2. Tumis bawang putih dan bawang merah iris.\n3. Masukkan tumisan ke dalam rebusan iga.\n4. Tambahkan wortel dan kentang.\n5. Beri garam, merica, dan pala bubuk.\n6. Masak hingga sayuran matang.\n7. Taburi bawang goreng dan seledri.\n8. Sajikan dengan sambal dan nasi hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Sop+Iga+Sapi', 1, NULL, '2026-07-10 14:14:39'),
(274, 6, 6, 'Sop Iga Kambing', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus iga kambing hingga empuk.\n2. Tumis bawang putih, bawang merah, dan jahe.\n3. Masukkan tumisan ke dalam rebusan iga.\n4. Tambahkan kentang dan wortel.\n5. Beri garam, merica, dan kayu manis.\n6. Masak hingga sayuran empuk.\n7. Taburi daun bawang dan bawang goreng.\n8. Sajikan hangat dengan emping.\n\n\nSumber: https://www.google.com/search?q=resep+Sop+Iga+Kambing', 1, NULL, '2026-07-10 14:14:39'),
(275, 6, 6, 'Sop Iga Tulang', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus iga tulang sapi hingga empuk.\n2. Tumis bawang putih cincang hingga harum.\n3. Masukkan tumisan ke dalam rebusan.\n4. Tambahkan potongan kentang dan wortel.\n5. Beri garam, merica, dan kaldu sapi.\n6. Masak hingga sayuran lunak.\n7. Taburi seledri dan bawang goreng.\n8. Sajikan hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Sop+Iga+Tulang', 1, NULL, '2026-07-10 14:14:39'),
(276, 6, 6, 'Sop Iga Kremes', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus iga sapi hingga empuk, tiriskan.\n2. Goreng iga sebentar hingga kecoklatan.\n3. Tumis bawang putih, bawang merah, jahe.\n4. Masukkan tumisan ke dalam air kaldu.\n5. Tambahkan sayuran, garam, dan merica.\n6. Sajikan iga goreng dengan kuah sop.\n7. Taburi kremes tepung di atasnya.\n8. Sop iga kremes siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Sop+Iga+Kremes', 1, NULL, '2026-07-10 14:14:39'),
(277, 7, 2, 'Tumis Kangkung Bawang', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Siangi kangkung, cuci bersih.\n2. Iris bawang merah dan bawang putih.\n3. Panaskan minyak, tumis bawang hingga harum.\n4. Masukkan kangkung, aduk cepat.\n5. Beri garam dan gula pasir.\n6. Tambahkan sedikit air.\n7. Masak hingga kangkung layu.\n8. Angkat dan sajikan segera.\n\n\nSumber: https://www.google.com/search?q=resep+Tumis+Kangkung+Bawang', 1, NULL, '2026-07-10 14:14:39'),
(278, 7, 2, 'Tumis Kangkung Tahu', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Siangi kangkung, cuci bersih.\n2. Potong tahu kotak, goreng setengah matang.\n3. Iris bawang merah dan bawang putih.\n4. Tumis bawang hingga harum, masukkan kangkung.\n5. Masukkan tahu, aduk rata.\n6. Beri garam, gula, dan kecap manis.\n7. Aduk hingga layu dan merata.\n8. Angkat dan sajikan.\n\n\nSumber: https://www.google.com/search?q=resep+Tumis+Kangkung+Tahu', 1, NULL, '2026-07-10 14:14:39'),
(279, 7, 2, 'Tumis Kangkung Kecap', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Siangi kangkung, cuci bersih.\n2. Iris bawang merah, bawang putih, dan cabai.\n3. Panaskan minyak, tumis bumbu iris hingga harum.\n4. Masukkan kangkung, aduk cepat.\n5. Tambahkan kecap manis dan garam.\n6. Aduk rata hingga kangkung layu.\n7. Tambahkan sedikit air.\n8. Angkat dan sajikan selagi hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Tumis+Kangkung+Kecap', 1, NULL, '2026-07-10 14:14:39'),
(280, 7, 2, 'Tumis Kangkung Terasi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Siangi kangkung, cuci bersih.\n2. Haluskan bawang merah, bawang putih, cabai, dan terasi.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Masukkan kangkung, aduk cepat.\n5. Beri garam dan gula.\n6. Aduk hingga kangkung layu.\n7. Angkat dan sajikan segera.\n8. Tumis kangkung terasi siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Tumis+Kangkung+Terasi', 1, NULL, '2026-07-10 14:14:39'),
(281, 7, 2, 'Tumis Kangkung Belacan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Siangi kangkung, cuci bersih.\n2. Haluskan bawang merah, bawang putih, cabai, dan belacan.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Masukkan kangkung, aduk cepat.\n5. Beri garam dan gula pasir.\n6. Aduk hingga kangkung layu.\n7. Angkat dan sajikan segera.\n8. Tumis kangkung belacan siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Tumis+Kangkung+Belacan', 1, NULL, '2026-07-10 14:14:39'),
(282, 3, 2, 'Capcay Sayur', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Iris wortel, kol, sawi hijau, dan kembang kol.\n2. Panaskan minyak, tumis bawang putih cincang.\n3. Masukkan wortel, masak hingga setengah matang.\n4. Masukkan sayuran lainnya.\n5. Tambahkan garam, merica, dan saus tiram.\n6. Tuang sedikit air, masak hingga sayuran matang.\n7. Kentalkan dengan larutan maizena jika suka.\n8. Angkat dan sajikan hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Capcay+Sayur', 1, NULL, '2026-07-10 14:14:39'),
(283, 3, 2, 'Capcay Ayam', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong dadu daging ayam.\n2. Iris wortel, kol, sawi, dan kembang kol.\n3. Tumis bawang putih cincang hingga harum.\n4. Masukkan ayam, masak hingga berubah warna.\n5. Masukkan sayuran, aduk rata.\n6. Tambahkan garam, merica, dan saus tiram.\n7. Tuang sedikit air, masak hingga matang.\n8. Angkat dan sajikan.\n\n\nSumber: https://www.google.com/search?q=resep+Capcay+Ayam', 1, NULL, '2026-07-10 14:14:39'),
(284, 3, 2, 'Capcay Seafood', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan udang, cumi, dan bakso ikan.\n2. Iris wortel, kol, sawi, dan kembang kol.\n3. Tumis bawang putih cincang hingga harum.\n4. Masukkan seafood, masak sebentar.\n5. Masukkan sayuran, aduk rata.\n6. Tambahkan garam, merica, dan saus tiram.\n7. Tuang sedikit air, masak hingga matang.\n8. Angkat dan sajikan hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Capcay+Seafood', 1, NULL, '2026-07-10 14:14:39'),
(285, 3, 2, 'Capcay Full Goreng', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong semua sayuran (wortel, kol, sawi, kembang kol).\n2. Potong bakso dan ayam tipis.\n3. Tumis bawang putih cincang hingga harum.\n4. Masukkan bakso dan ayam, masak hingga matang.\n5. Masukkan sayuran, aduk cepat.\n6. Tambahkan garam, merica, dan saus tiram.\n7. Masak dengan api besar hingga sayuran setengah matang.\n8. Angkat dan sajikan.\n\n\nSumber: https://www.google.com/search?q=resep+Capcay+Full+Goreng', 1, NULL, '2026-07-10 14:14:39'),
(286, 3, 2, 'Capcay Kuah Santan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Iris wortel, kol, sawi, dan kembang kol.\n2. Tumis bawang putih dan bawang merah cincang.\n3. Masukkan sayuran, aduk rata.\n4. Tambahkan santan, garam, merica, dan gula.\n5. Masak dengan api sedang sambil diaduk.\n6. Masukkan udang atau ayam jika suka.\n7. Masak hingga sayuran matang dan kuah mengental.\n8. Angkat dan sajikan hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Capcay+Kuah+Santan', 1, NULL, '2026-07-10 14:14:39'),
(287, 4, 2, 'Pepes Ikan Mas', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan mas, lumuri air jeruk nipis dan garam.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe.\n3. Campur bumbu halus dengan daun kemangi dan irisan tomat.\n4. Ambil selembar daun pisang, letakkan ikan.\n5. Bungkus ikan dengan bumbu, semat lidi.\n6. Kukus pepes selama 30 menit.\n7. Bakar sebentar di atas bara untuk aroma.\n8. Pepes ikan mas siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Pepes+Ikan+Mas', 1, NULL, '2026-07-10 14:14:39'),
(288, 4, 2, 'Pepes Ikan Nila', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan ikan nila, kerat kedua sisi.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, kemiri.\n3. Lumuri ikan dengan bumbu halus.\n4. Tambahkan daun kemangi dan tomat iris.\n5. Bungkus dengan daun pisang.\n6. Kukus selama 25-30 menit.\n7. Bakar sebentar hingga daun pisang kering.\n8. Pepes ikan nila siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Pepes+Ikan+Nila', 1, NULL, '2026-07-10 14:14:39'),
(289, 4, 2, 'Pepes Patin', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong ikan patin ukuran sedang, lumuri jeruk nipis.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe.\n3. Campur bumbu dengan daun kemangi dan serai iris.\n4. Bungkus ikan patin dengan daun pisang.\n5. Semat dengan lidi.\n6. Kukus selama 30 menit hingga matang.\n7. Bakar sebentar untuk aroma.\n8. Pepes patin siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Pepes+Patin', 1, NULL, '2026-07-10 14:14:39'),
(290, 4, 2, 'Pepes Tuna', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong tuna dadu, lumuri air jeruk nipis.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, kemiri.\n3. Campur tuna dengan bumbu, daun kemangi, dan tomat.\n4. Bungkus dengan daun pisang.\n5. Semat lidi di kedua ujung.\n6. Kukus selama 25 menit.\n7. Bakar sebentar.\n8. Pepes tuna siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Pepes+Tuna', 1, NULL, '2026-07-10 14:14:39'),
(291, 4, 2, 'Pepes Cumi', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Bersihkan cumi, potong cincin.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe.\n3. Campur cumi dengan bumbu halus dan daun kemangi.\n4. Tambahkan potongan tomat dan cabai rawit utuh.\n5. Bungkus dengan daun pisang.\n6. Kukus selama 20 menit.\n7. Bakar sebentar.\n8. Pepes cumi siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Pepes+Cumi', 1, NULL, '2026-07-10 14:14:39'),
(292, 5, 5, 'Perkedel Kentang', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Kupas kentang, potong dadu, goreng hingga empuk.\n2. Haluskan kentang selagi hangat.\n3. Campur dengan bawang goreng, seledri, garam, dan merica.\n4. Tambahkan kuning telur, aduk rata.\n5. Bentuk bulat pipih.\n6. Kocok putih telur untuk lapisan.\n7. Celupkan perkedel ke putih telur.\n8. Goreng hingga kuning keemasan.\n\n\nSumber: https://www.google.com/search?q=resep+Perkedel+Kentang', 1, NULL, '2026-07-10 14:14:39'),
(293, 5, 5, 'Perkedel Tahu', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Hancurkan tahu putih hingga halus.\n2. Campur dengan irisan daun bawang, garam, dan merica.\n3. Tambahkan telur dan sedikit tepung terigu.\n4. Aduk rata hingga bisa dibentuk.\n5. Bentuk bulat pipih.\n6. Panaskan minyak goreng.\n7. Goreng perkedel hingga kecoklatan.\n8. Angkat dan tiriskan, sajikan hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Perkedel+Tahu', 1, NULL, '2026-07-10 14:14:39'),
(294, 5, 5, 'Perkedel Jagung', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Serut jagung manis dari bonggolnya.\n2. Haluskan jagung kasar dengan blender.\n3. Campur jagung dengan telur, tepung terigu, dan daun bawang.\n4. Beri garam dan merica.\n5. Aduk rata hingga menjadi adonan.\n6. Sendok adonan, goreng dalam minyak panas.\n7. Goreng hingga kuning keemasan.\n8. Angkat dan tiriskan, sajikan dengan saus.\n\n\nSumber: https://www.google.com/search?q=resep+Perkedel+Jagung', 1, NULL, '2026-07-10 14:14:39'),
(295, 5, 5, 'Perkedel Daging', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Campur daging giling dengan kentang halus.\n2. Tambahkan bawang goreng, seledri, garam, dan merica.\n3. Masukkan telur dan sedikit pala bubuk.\n4. Aduk rata hingga kalis.\n5. Bentuk bulat pipih.\n6. Celupkan ke kocokan telur.\n7. Goreng dalam minyak panas hingga matang.\n8. Angkat dan tiriskan.\n\n\nSumber: https://www.google.com/search?q=resep+Perkedel+Daging', 1, NULL, '2026-07-10 14:14:39'),
(296, 5, 5, 'Perkedel Mie', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Rebus mie instan hingga matang, tiriskan.\n2. Hancurkan mie dengan garpu.\n3. Campur dengan telur, irisan daun bawang, dan bumbu mie.\n4. Tambahkan sedikit tepung terigu.\n5. Aduk rata hingga bisa dibentuk.\n6. Bentuk bulat pipih.\n7. Goreng dalam minyak panas hingga kecoklatan.\n8. Angkat dan sajikan hangat.\n\n\nSumber: https://www.google.com/search?q=resep+Perkedel+Mie', 1, NULL, '2026-07-10 14:14:39'),
(297, 6, 2, 'Rujak Mangga', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Kupas mangga muda, potong memanjang.\n2. Haluskan gula merah, cabai, garam, dan terasi.\n3. Tambahkan air asam jawa, aduk rata.\n4. Campur bumbu dengan potongan mangga.\n5. Aduk hingga tercampur rata.\n6. Diamkan sebentar agar bumbu meresap.\n7. Sajikan dengan taburan kacang tanah goreng.\n8. Rujak mangga siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rujak+Mangga', 1, NULL, '2026-07-10 14:14:39');
INSERT INTO `resep` (`id`, `id_user`, `id_kategori`, `judul`, `deskripsi`, `langkah_memasak`, `jumlah_porsi`, `foto`, `created_at`) VALUES
(298, 6, 2, 'Rujak Nanas', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Kupas nanas, potong dadu kecil.\n2. Haluskan gula merah, cabai, garam, dan terasi.\n3. Tambahkan air asam jawa.\n4. Campur bumbu dengan nanas.\n5. Aduk rata.\n6. Diamkan sebentar.\n7. Sajikan dengan taburan kacang tanah.\n8. Rujak nanas siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rujak+Nanas', 1, NULL, '2026-07-10 14:14:39'),
(299, 6, 2, 'Rujak Pepaya', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Kupas pepaya muda, potong tipis panjang.\n2. Haluskan gula merah, cabai rawit, garam, dan terasi.\n3. Tambahkan air asam jawa.\n4. Campur bumbu dengan pepaya.\n5. Aduk hingga bumbu merata.\n6. Tambahkan potongan timun.\n7. Sajikan dengan taburan kacang.\n8. Rujak pepaya siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rujak+Pepaya', 1, NULL, '2026-07-10 14:14:40'),
(300, 6, 2, 'Rujak Jambu', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong jambu air dan jambu biji sesuai selera.\n2. Haluskan gula merah, cabai, garam, dan terasi.\n3. Tambahkan air asam jawa.\n4. Campur potongan jambu dengan bumbu.\n5. Aduk rata.\n6. Diamkan sebentar.\n7. Sajikan dengan taburan kacang tanah.\n8. Rujak jambu siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rujak+Jambu', 1, NULL, '2026-07-10 14:14:40'),
(301, 6, 2, 'Rujak Komplit', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Potong mangga muda, pepaya muda, nanas, timun, dan jambu.\n2. Haluskan gula merah, cabai, garam, terasi, dan kacang tanah.\n3. Tambahkan air asam jawa.\n4. Campur semua buah dengan bumbu.\n5. Aduk hingga rata.\n6. Diamkan sebentar agar meresap.\n7. Sajikan rujak komplit segar.\n8. Rujak komplit siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Rujak+Komplit', 1, NULL, '2026-07-10 14:14:40'),
(302, 7, 2, 'Bubur Ayam Polos', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Cuci beras, masak dengan air hingga menjadi bubur.\n2. Tambahkan santan dan garam, aduk rata.\n3. Rebus ayam hingga empuk, suwir-suwir.\n4. Sajikan bubur di mangkuk.\n5. Tambahkan suwiran ayam di atasnya.\n6. Taburi bawang goreng dan seledri.\n7. Tambahkan kecap manis dan sambal.\n8. Bubur ayam polos siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bubur+Ayam+Polos', 1, NULL, '2026-07-10 14:14:40'),
(303, 7, 2, 'Bubur Ayam Telur', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Masak beras hingga menjadi bubur dengan santan.\n2. Rebus ayam hingga empuk, suwir-suwir.\n3. Rebus telur, kupas, belah dua.\n4. Sajikan bubur di mangkuk.\n5. Tambahkan suwiran ayam dan telur rebus.\n6. Taburi bawang goreng dan seledri.\n7. Tambahkan kecap manis dan sambal.\n8. Bubur ayam telur siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bubur+Ayam+Telur', 1, NULL, '2026-07-10 14:14:40'),
(304, 7, 2, 'Bubur Ayam Cakwe', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Masak beras hingga menjadi bubur dengan santan.\n2. Rebus ayam hingga empuk, suwir-suwir.\n3. Potong cakwe kecil-kecil.\n4. Sajikan bubur di mangkuk.\n5. Tambahkan suwiran ayam dan potongan cakwe.\n6. Taburi bawang goreng dan seledri.\n7. Tambahkan kecap manis dan sambal.\n8. Bubur ayam cakwe siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bubur+Ayam+Cakwe', 1, NULL, '2026-07-10 14:14:40'),
(305, 7, 2, 'Bubur Ayam Komplit', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Masak beras hingga menjadi bubur dengan santan.\n2. Rebus ayam hingga empuk, suwir-suwir.\n3. Rebus telur, kupas.\n4. Potong cakwe dan siapkan kerupuk.\n5. Sajikan bubur di mangkuk besar.\n6. Tambahkan suwiran ayam, telur, cakwe, dan kerupuk.\n7. Taburi bawang goreng, seledri, kecap manis, dan sambal.\n8. Bubur ayam komplit siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bubur+Ayam+Komplit', 1, NULL, '2026-07-10 14:14:40'),
(306, 7, 2, 'Bubur Ayam Gorengan', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Masak beras hingga menjadi bubur dengan santan.\n2. Rebus ayam hingga empuk, suwir-suwir.\n3. Goreng tahu, tempe, dan bakwan untuk gorengan.\n4. Sajikan bubur di mangkuk.\n5. Tambahkan suwiran ayam.\n6. Taburi bawang goreng, seledri, kecap manis, dan sambal.\n7. Sajikan dengan aneka gorengan di samping.\n8. Bubur ayam gorengan siap dinikmati.\n\n\nSumber: https://www.google.com/search?q=resep+Bubur+Ayam+Gorengan', 1, NULL, '2026-07-10 14:14:40'),
(413, 4, 2, 'Lumpia Semarang', 'Resep Lumpia Semarang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lumpia+semarang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung terigu, telur, dan air hingga adonan kental untuk kulit lumpia.\n2. Panaskan wajan anti lengket, buat kulit lumpia tipis-tipis hingga habis.\n3. Tumis bawang putih hingga harum, masukkan daging ayam cincang dan rebung.\n4. Tambahkan daun bawang, gula pasir, dan garam. Aduk rata, masak hingga matang.\n5. Ambil selembar kulit lumpia, isi dengan tumisan ayam rebung.\n6. Lipat kulit lumpia seperti amplop, rekatkan dengan sisa adonan tepung.\n7. Goreng lumpia dalam minyak panas hingga kuning kecoklatan.\n8. Tiriskan dan sajikan dengan saus sambal atau cabai rawit hijau.\n9. Lumpia Semarang siap dinikmati selagi hangat.\n10. Hidangkan sebagai camilan atau lauk pendamping nasi.\n', 1, NULL, '2026-07-13 15:21:38'),
(414, 5, 2, 'Lumpia Basah', 'Resep Lumpia Basah khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lumpia+basah\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat adonan kulit dari tepung terigu dan telur, masak di wajan anti lengket tipis-tipis.\n2. Tumis bawang putih, masukkan daging ayam cincang hingga berubah warna.\n3. Tambahkan toge dan daun bawang, aduk sebentar, angkat.\n4. Haluskan kacang tanah goreng dengan gula merah untuk saus.\n5. Ambil kulit lumpia, beri isian tumisan ayam toge.\n6. Lipat lumpia seperti amplop tanpa digoreng.\n7. Siram dengan saus kacang di atasnya.\n8. Taburi dengan bawang goreng sebagai pelengkap.\n9. Sajikan selagi kulit masih lembut.\n', 1, NULL, '2026-07-13 15:21:38'),
(415, 6, 2, 'Lumpia Goreng Isi Sayur', 'Resep Lumpia Goreng Isi Sayur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lumpia+goreng+isi+sayur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat adonan kulit dari tepung terigu, air, dan sedikit garam hingga kental.\n2. Masak adonan di wajan anti lengket menjadi lembaran tipis.\n3. Iris wortel dan kol tipis memanjang.\n4. Tumis bawang putih hingga harum, masukkan wortel, kol, dan toge.\n5. Tambahkan garam dan daun bawang, masak hingga sayuran layu.\n6. Ambil kulit lumpia, isi dengan tumisan sayur, lipat rapi.\n7. Rekatkan ujung lumpia dengan larutan tepung.\n8. Goreng dalam minyak panas hingga kuning keemasan.\n9. Tiriskan dan sajikan dengan saus sambal.\n', 1, NULL, '2026-07-13 15:21:38'),
(416, 7, 2, 'Pastel Tutup', 'Resep Pastel Tutup khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+pastel+tutup\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus kentang hingga empuk, haluskan.\n2. Tumis bawang putih dan daging ayam cincang hingga matang.\n3. Campur kentang halus dengan tumisan ayam, tambahkan wortel serut dan daun bawang.\n4. Buat adonan kulit dari tepung terigu, margarin, telur, dan sedikit air.\n5. Uleni hingga kalis, gilas tipis, cetak bundar.\n6. Isi adonan kulit dengan campuran kentang ayam, lipat setengah lingkaran.\n7. Tekan tepi pastel dengan garpu untuk merekatkan.\n8. Goreng pastel dalam minyak panas hingga kuning kecoklatan.\n9. Angkat dan tiriskan. Sajikan dengan cabai rawit hijau.\n', 1, NULL, '2026-07-13 15:21:38'),
(417, 8, 2, 'Pastel Isi Daging', 'Resep Pastel Isi Daging khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+pastel+isi+daging\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat kulit pastel: campur tepung terigu, margarin, telur, dan air hangat.\n2. Uleni adonan hingga kalis, diamkan 15 menit.\n3. Tumis bawang putih cincang hingga harum, masukkan daging sapi cincang.\n4. Tambahkan wortel dan buncis yang dipotong dadu kecil.\n5. Beri merica bubuk dan garam, masak hingga sayuran empuk.\n6. Ambil adonan kulit, gilas tipis, cetak bundar.\n7. Isi dengan tumisan daging, lipat setengah lingkaran, tekan tepi dengan garpu.\n8. Goreng pastel dalam minyak panas sedang hingga kuning keemasan.\n9. Tiriskan minyak berlebih, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:38'),
(418, 4, 2, 'Risoles Mayo', 'Resep Risoles Mayo khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+risoles+mayo\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat kulit risoles: campur tepung terigu, telur, dan susu cair hingga licin.\n2. Masak adonan di wajan anti lengket tipis-tipis hingga matang, sisihkan.\n3. Tumis bawang putih cincang, masukkan daging ayam cincang hingga matang.\n4. Campur tumisan ayam dengan mayones dan daun bawang.\n5. Ambil selembar kulit risoles, beri isian mayones ayam.\n6. Lipat amplop, celup ke kocokan telur, gulingkan di tepung roti.\n7. Goreng risoles dalam minyak panas hingga kuning kecoklatan.\n8. Tiriskan dan sajikan selagi hangat.\n9. Risoles mayo cocok sebagai camilan atau lauk pelengkap.\n', 1, NULL, '2026-07-13 15:21:38'),
(419, 5, 2, 'Risoles Ragout', 'Resep Risoles Ragout khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+risoles+ragout\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat kulit risoles dari campuran tepung, telur, dan susu cair.\n2. Panaskan margarin, tumis bawang bombay cincang hingga harum.\n3. Masukkan daging ayam cincang, masak hingga berubah warna.\n4. Tambahkan wortel serut dan susu cair, aduk hingga mengental sebagai ragout.\n5. Dinginkan ragout sebentar agar mudah diisi.\n6. Ambil kulit risoles, isi dengan ragout ayam wortel.\n7. Lipat amplop, celup telur, gulingkan di tepung roti.\n8. Goreng hingga kuning kecoklatan, angkat dan tiriskan.\n9. Sajikan hangat dengan saus sambal atau saus tomat.\n', 1, NULL, '2026-07-13 15:21:38'),
(420, 6, 2, 'Risoles Sayur', 'Resep Risoles Sayur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+risoles+sayur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat adonan kulit dari tepung terigu, telur, dan susu cair.\n2. Masak di wajan anti lengket menjadi lembaran tipis.\n3. Potong wortel, buncis, dan kol kecil-kecil.\n4. Tumis bawang putih, masukkan semua sayuran dan daun bawang.\n5. Tambahkan sedikit garam, masak hingga sayuran layu.\n6. Ambil kulit risoles, beri isian sayur, lipat amplop.\n7. Celup ke kocokan telur, balut dengan tepung roti.\n8. Goreng dalam minyak panas hingga keemasan.\n9. Sajikan hangat dengan saus kacang atau sambal.\n', 1, NULL, '2026-07-13 15:21:38'),
(421, 7, 2, 'Samosa Daging', 'Resep Samosa Daging khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+samosa+daging\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus kentang hingga empuk, haluskan kasar.\n2. Tumis bawang bombay dan bawang putih cincang hingga harum.\n3. Masukkan daging sapi cincang, masak hingga berubah warna.\n4. Tambahkan kentang halus, bubuk kari, garam, dan daun bawang. Aduk rata.\n5. Buat adonan kulit dari tepung terigu, minyak, air, dan garam.\n6. Uleni hingga kalis, gilas tipis, potong segitiga.\n7. Letakkan isian di tengah segitiga, lipat membentuk segitiga samosa.\n8. Rekatkan tepi dengan air, tekan rapat.\n9. Goreng samosa dalam minyak panas hingga kuning kecoklatan.\n10. Sajikan dengan saus sambal atau chutney.\n', 1, NULL, '2026-07-13 15:21:38'),
(422, 8, 2, 'Pangsit Goreng Isi', 'Resep Pangsit Goreng Isi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+pangsit+goreng+isi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat kulit pangsit dari tepung terigu, telur, dan air, uleni hingga kalis.\n2. Gilas adonan tipis-tipis, potong kotak-kotak.\n3. Campur daging ayam cincang dengan bawang putih halus, daun bawang, dan tepung tapioka.\n4. Tambahkan merica dan garam ke dalam isian, aduk rata.\n5. Ambil selembar kulit pangsit, isi dengan adonan ayam.\n6. Lipat diagonal membentuk segitiga, rekatkan tepi dengan air.\n7. Goreng pangsit dalam minyak panas hingga kuning kecoklatan.\n8. Tiriskan, sajikan dengan saus sambal.\n9. Pangsit goreng cocok untuk camilan atau pelengkap bakso.\n', 1, NULL, '2026-07-13 15:21:39'),
(423, 4, 2, 'Pangsit Rebus', 'Resep Pangsit Rebus khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+pangsit+rebus\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung terigu, telur, air, dan garam, uleni hingga kalis.\n2. Gilas tipis, potong kotak untuk kulit pangsit.\n3. Campur daging ayam cincang, bawang putih halus, daun bawang, dan tepung tapioka.\n4. Beri merica dan garam, aduk hingga rata.\n5. Isi kulit pangsit dengan adonan ayam, lipat segitiga, rekatkan.\n6. Didihkan air dalam panci, rebus pangsit hingga mengapung.\n7. Angkat pangsit, tiriskan.\n8. Sajikan dengan kuah kaldu ayam dan taburan daun bawang.\n9. Pangsit rebus nikmat disantap selagi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(424, 5, 2, 'Siomay Ayam', 'Resep Siomay Ayam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+siomay+ayam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan daging ayam bersama bawang putih dalam food processor.\n2. Campur dengan tepung tapioka, telur, garam, dan merica.\n3. Tambahkan daun bawang iris dan wortel serut, aduk rata.\n4. Bentuk adonan bulat-bulat atau sesuai selera.\n5. Kukus siomay dalam dandang panas selama 15-20 menit hingga matang.\n6. Siapkan bumbu kacang: haluskan kacang tanah goreng dengan gula merah dan cabai.\n7. Siram siomay dengan bumbu kacang, tambahkan kecap manis.\n8. Taburi dengan bawang goreng dan jeruk nipis.\n9. Sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(425, 6, 2, 'Siomay Ikan', 'Resep Siomay Ikan khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+siomay+ikan\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kukus atau rebus labu siam hingga empuk, haluskan.\n2. Haluskan daging ikan tuna bersama bawang putih.\n3. Campur ikan halus dengan labu siam halus, tepung tapioka, dan telur.\n4. Beri garam dan merica, aduk rata hingga bisa dibentuk.\n5. Bentuk adonan bulat lonjong atau sesuai selera.\n6. Kukus dalam dandang panas selama 20 menit hingga matang.\n7. Haluskan kacang tanah goreng dengan cabai dan gula merah untuk saus.\n8. Siram siomay dengan saus kacang dan kecap manis.\n9. Taburi bawang goreng, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(426, 7, 2, 'Batagor', 'Resep Batagor khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+batagor\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan daging ikan tuna bersama bawang putih.\n2. Campur dengan tepung tapioka, telur, garam, dan merica.\n3. Tambahkan daun bawang iris, aduk rata.\n4. Potong tahu putih segitiga, belah tengahnya.\n5. Isi tahu dengan adonan ikan, rapikan.\n6. Kukus tahu isi dan sisa adonan dibentuk bakso selama 15 menit.\n7. Goreng tahu isi dan siomay dalam minyak panas hingga kecoklatan.\n8. Siapkan bumbu kacang: haluskan kacang tanah, cabai, gula merah.\n9. Potong-potong batagor, siram dengan bumbu kacang dan kecap.\n10. Taburi jeruk nipis dan bawang goreng, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(427, 8, 2, 'Tahu Sumedang', 'Resep Tahu Sumedang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+sumedang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih bentuk dadu atau segitiga.\n2. Rendam tahu dalam air garam dan bawang putih halus selama 15 menit.\n3. Panaskan minyak goreng dalam wajan.\n4. Goreng tahu dalam minyak panas hingga kulitnya kering dan renyah.\n5. Balik tahu sesekali agar matang merata.\n6. Angkat dan tiriskan minyak berlebih.\n7. Sajikan tahu sumedang dengan cabai rawit hijau dan kecap manis.\n8. Tahu sumedang enak dinikmati selagi hangat dan renyah.\n', 1, NULL, '2026-07-13 15:21:39'),
(428, 4, 2, 'Tahu Cabe Garam', 'Resep Tahu Cabe Garam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+cabe+garam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih bentuk dadu kecil.\n2. Baluri tahu dengan campuran tepung terigu, garam, dan merica.\n3. Goreng tahu dalam minyak panas hingga renyah, angkat.\n4. Cincang kasar bawang putih dan cabai rawit.\n5. Panaskan sedikit minyak, tumis bawang putih hingga harum kekuningan.\n6. Masukkan cabai rawit dan daun bawang, aduk cepat.\n7. Masukkan tahu goreng, aduk rata dengan bumbu.\n8. Sajikan tahu cabe garam selagi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(429, 5, 2, 'Tahu Crispy', 'Resep Tahu Crispy khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+crispy\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih tipis-tipis atau bentuk stik.\n2. Campur tepung terigu, tepung beras, garam, merica, dan bawang putih bubuk.\n3. Buat adonan basah dengan mencampur sebagian tepung dengan air.\n4. Celupkan tahu ke adonan basah, lalu gulingkan di adonan kering.\n5. Remas-remas agar tepung menempel sempurna.\n6. Panaskan minyak, goreng tahu hingga kuning keemasan.\n7. Angkat dan tiriskan.\n8. Sajikan dengan saus sambal atau mayones.\n', 1, NULL, '2026-07-13 15:21:39'),
(430, 6, 2, 'Tempe Mendoan', 'Resep Tempe Mendoan khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tempe+mendoan\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tempe tipis-tipis melebar.\n2. Campur tepung terigu, tepung beras, bawang putih halus, kunyit bubuk, dan garam.\n3. Tambahkan air dan daun bawang iris, aduk hingga adonan kental.\n4. Panaskan minyak dalam wajan.\n5. Celupkan potongan tempe ke dalam adonan tepung hingga terbalut rata.\n6. Goreng dalam minyak panas sebentar saja (tidak terlalu kering).\n7. Angkat saat tepung mulai menguning, mendoan khas setengah matang.\n8. Sajikan dengan cabai rawit hijau atau kecap pedas.\n', 1, NULL, '2026-07-13 15:21:39'),
(431, 7, 2, 'Cireng Isi', 'Resep Cireng Isi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cireng+isi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung tapioka dan tepung terigu dengan perbandingan 3:1.\n2. Tumis bawang putih cincang dan daun bawang, masukkan telur orak-arik.\n3. Tambahkan garam dan merica untuk isian telur.\n4. Rebus sedikit air hingga mendidih, tuang ke campuran tepung sambil diaduk.\n5. Uleni adonan hingga kalis, ambil sedikit, pipihkan.\n6. Isi dengan tumisan telur, tutup rapat, bentuk bulat lonjong.\n7. Goreng cireng dalam minyak panas hingga kuning kecoklatan.\n8. Angkat dan tiriskan.\n9. Sajikan cireng isi dengan bumbu rujak atau saus sambal.\n', 1, NULL, '2026-07-13 15:21:39'),
(432, 8, 2, 'Cilok Bumbu Kacang', 'Resep Cilok Bumbu Kacang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cilok+bumbu+kacang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung tapioka dan tepung terigu, tambahkan bawang putih halus.\n2. Tuang air panas sedikit demi sedikit sambil diaduk, uleni hingga kalis.\n3. Tambahkan daun bawang iris, bentuk bulat-bulat kecil.\n4. Rebus cilok dalam air mendidih hingga mengapung, angkat.\n5. Haluskan kacang tanah goreng, gula merah, cabai rawit, dan garam.\n6. Tambahkan air hangat ke bumbu kacang hingga kekentalan yang diinginkan.\n7. Campur cilok dengan bumbu kacang, aduk rata.\n8. Taburi bawang goreng dan kecap manis sesuai selera.\n9. Sajikan cilok bumbu kacang selagi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(433, 4, 2, 'Cilok Kuah', 'Resep Cilok Kuah khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cilok+kuah\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung tapioka dan terigu dengan bawang putih halus dan garam.\n2. Tuang air panas, uleni hingga kalis.\n3. Bentuk adonan menjadi bulatan-bulatan kecil.\n4. Rebus cilok dalam air mendidih hingga mengapung, tiriskan.\n5. Didihkan kaldu ayam, tambahkan merica bubuk dan garam.\n6. Masukkan cilok ke dalam kuah kaldu mendidih.\n7. Taburi daun bawang dan seledri iris.\n8. Sajikan cilok kuah selagi hangat.\n9. Tambahkan saus sambal dan kecap manis sesuai selera.\n', 1, NULL, '2026-07-13 15:21:39'),
(434, 5, 2, 'Pisang Goreng Keju', 'Resep Pisang Goreng Keju khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+pisang+goreng+keju\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas pisang, potong belah memanjang.\n2. Campur tepung terigu, tepung beras, gula pasir, dan air hingga adonan kental.\n3. Celupkan potongan pisang ke dalam adonan tepung.\n4. Goreng dalam minyak panas hingga kuning keemasan.\n5. Angkat dan tiriskan sebentar.\n6. Parut keju cheddar di atas pisang goreng.\n7. Kucuri dengan susu kental manis.\n8. Sajikan pisang goreng keju selagi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(435, 6, 2, 'Ubi Goreng', 'Resep Ubi Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ubi+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas ubi jalar, cuci bersih, potong tipis memanjang atau bulat.\n2. Campur tepung terigu, gula pasir, vanili, dan sedikit air.\n3. Celupkan ubi ke adonan tepung.\n4. Panaskan minyak dalam wajan.\n5. Goreng ubi hingga matang dan kuning kecoklatan.\n6. Balik sekali agar matang merata.\n7. Angkat dan tiriskan minyak.\n8. Sajikan ubi goreng hangat sebagai camilan.\n', 1, NULL, '2026-07-13 15:21:39'),
(436, 7, 2, 'Singkong Goreng', 'Resep Singkong Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+singkong+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas singkong, potong-potong sesuai selera.\n2. Rebus singkong dengan bawang putih halus dan garam hingga empuk.\n3. Tiriskan singkong, biarkan dingin.\n4. Panaskan minyak dalam wajan.\n5. Goreng singkong hingga kuning kecoklatan dan renyah di luar.\n6. Angkat dan tiriskan.\n7. Taburi dengan daun bawang iris atau bumbu tabur.\n8. Sajikan selagi hangat sebagai camilan.\n', 1, NULL, '2026-07-13 15:21:39'),
(437, 8, 2, 'Ayam Bakar Taliwang', 'Resep Ayam Bakar Taliwang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+bakar+taliwang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan cabai merah, cabai rawit, bawang merah, bawang putih, dan terasi.\n2. Lumuri ayam dengan bumbu halus, tambahkan gula merah dan garam.\n3. Kucuri jeruk nipis, diamkan 30 menit agar bumbu meresap.\n4. Panaskan panggangan atau grill pan.\n5. Bakar ayam sambil sesekali dioles sisa bumbu.\n6. Balik ayam agar matang merata, bakar hingga kecoklatan.\n7. Angkat dan sajikan dengan lalapan dan sambal.\n8. Ayam bakar Taliwang khas Lombok siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:39'),
(438, 4, 2, 'Ayam Betutu', 'Resep Ayam Betutu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+betutu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe, dan lengkuas.\n2. Tumis bumbu halus hingga harum, masukkan daun salam dan sereh geprek.\n3. Lumuri ayam dengan bumbu tumis, pijat-pijat agar meresap.\n4. Bungkus ayam dengan daun pisang.\n5. Kukus ayam dalam dandang panas selama 45 menit.\n6. Panggang sebentar ayam betutu di atas grill atau oven.\n7. Angkat dan sajikan dengan nasi hangat.\n8. Ayam betutu khas Bali siap disantap.\n', 1, NULL, '2026-07-13 15:21:39'),
(439, 5, 2, 'Ayam Pop', 'Resep Ayam Pop khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+pop\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus ayam dengan air kelapa, bawang putih, jahe, kunyit, dan garam.\n2. Tambahkan daun salam dan sereh geprek.\n3. Rebus hingga ayam empuk dan air menyusut.\n4. Angkat ayam, tiriskan dari kuah.\n5. Panaskan minyak, goreng ayam sebentar saja hingga kulit agak kering.\n6. Ayam pop tidak digoreng hingga coklat, cukup sebentar.\n7. Sajikan dengan sambal merah dan sayur daun singkong.\n8. Ayam pop khas Padang siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:39'),
(440, 6, 2, 'Ayam Cincane', 'Resep Ayam Cincane khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+cincane\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam menjadi beberapa bagian, cuci bersih.\n2. Kucuri ayam dengan jeruk nipis, diamkan 10 menit.\n3. Haluskan cabai merah, bawang merah, bawang putih, jahe, dan kunyit.\n4. Tumis bumbu halus hingga harum, masukkan gula merah.\n5. Masukkan ayam, aduk rata dengan bumbu.\n6. Tambahkan air, masak hingga ayam empuk dan bumbu meresap.\n7. Panggang ayam di atas bara api atau grill hingga kecoklatan.\n8. Sajikan dengan nasi hangat dan lalapan.\n9. Ayam cincane khas Kalimantan Timur siap disantap.\n', 1, NULL, '2026-07-13 15:21:39'),
(441, 7, 2, 'Ayam Woku', 'Resep Ayam Woku khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+woku\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil, cuci bersih.\n2. Haluskan cabai rawit, bawang merah, bawang putih, jahe, dan kunyit.\n3. Tumis bumbu halus hingga harum, masukkan daun jeruk.\n4. Masukkan ayam, aduk hingga berubah warna.\n5. Tambahkan air, masak hingga ayam empuk.\n6. Masukkan daun bawang iris, aduk sebentar.\n7. Koreksi rasa, angkat.\n8. Sajikan ayam woku dengan nasi hangat.\n9. Ayam woku khas Manado siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:39'),
(442, 8, 2, 'Ayam Rica-rica', 'Resep Ayam Rica-rica khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+rica-rica\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam sesuai selera, cuci bersih.\n2. Haluskan cabai rawit, cabai merah, bawang merah, bawang putih, dan jahe.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan daun jeruk dan sereh geprek, aduk.\n5. Masukkan ayam, aduk rata dengan bumbu.\n6. Tambahkan air, masak hingga ayam empuk dan bumbu meresap.\n7. Koreksi rasa, masak hingga kuah mengental.\n8. Sajikan ayam rica-rica dengan nasi hangat.\n9. Ayam rica-rica khas Manado siap disantap.\n', 1, NULL, '2026-07-13 15:21:39'),
(443, 4, 2, 'Ayam Bumbu Rujak', 'Resep Ayam Bumbu Rujak khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+bumbu+rujak\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam menjadi beberapa bagian.\n2. Haluskan cabai merah, bawang merah, bawang putih, dan kemiri.\n3. Tumis bumbu halus hingga harum, masukkan daun salam.\n4. Masukkan ayam, aduk rata dengan bumbu.\n5. Tambahkan gula merah dan santan kelapa.\n6. Masak dengan api kecil hingga ayam empuk dan bumbu meresap.\n7. Aduk sesekali agar santan tidak pecah.\n8. Koreksi rasa, angkat.\n9. Sajikan ayam bumbu rujak dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(444, 5, 2, 'Ayam Lodho', 'Resep Ayam Lodho khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+lodho\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bakar ayam sebentar hingga kulit kecoklatan.\n2. Haluskan bawang merah, bawang putih, cabai, kunyit, jahe, dan kemiri.\n3. Tumis bumbu halus hingga harum, masukkan daun jeruk.\n4. Masukkan ayam bakar, aduk rata.\n5. Tuang santan, masak dengan api kecil.\n6. Aduk perlahan agar santan tidak pecah.\n7. Masak hingga ayam empuk dan kuah mengental.\n8. Koreksi rasa, angkat.\n9. Sajikan ayam lodho khas Tulungagung dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(445, 6, 2, 'Ayam Bakakak', 'Resep Ayam Bakakak khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+bakakak\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Belah ayam tanpa putus, pipihkan.\n2. Haluskan bawang merah, bawang putih, jahe, dan cabai rawit.\n3. Lumuri ayam dengan bumbu halus, kecap manis, dan gula merah.\n4. Diamkan selama 30 menit agar bumbu meresap.\n5. Panaskan panggangan atau grill.\n6. Bakar ayam sambil dioles sisa bumbu.\n7. Balik ayam agar matang merata.\n8. Sajikan ayam bakakak dengan lalapan dan sambal.\n', 1, NULL, '2026-07-13 15:21:39'),
(446, 7, 2, 'Ayam Panggang Bumbu Kuning', 'Resep Ayam Panggang Bumbu Kuning khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+panggang+bumbu+kuning\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan kunyit, bawang putih, kemiri, jahe, dan garam.\n2. Lumuri ayam dengan bumbu halus hingga rata.\n3. Tumis sisa bumbu dengan sedikit minyak, masukkan daun salam dan sereh.\n4. Masukkan ayam, tambahkan air, rebus hingga empuk.\n5. Angkat ayam dari kuah.\n6. Panggang ayam di oven atau grill hingga kecoklatan.\n7. Oles sisa bumbu saat memanggang.\n8. Sajikan dengan nasi hangat dan lalapan.\n', 1, NULL, '2026-07-13 15:21:39'),
(447, 8, 2, 'Ayam Serundeng', 'Resep Ayam Serundeng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+serundeng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Parut kelapa, sangrai setengah kering.\n2. Haluskan bawang merah, bawang putih, kunyit, kemiri, dan garam.\n3. Lumuri ayam dengan bumbu halus, tambahkan daun salam.\n4. Rebus ayam hingga empuk, angkat.\n5. Goreng ayam dalam minyak panas hingga kecoklatan.\n6. Campur kelapa sangrai dengan sisa bumbu, goreng hingga kering.\n7. Taburkan serundeng kelapa di atas ayam goreng.\n8. Sajikan dengan nasi hangat dan sambal terasi.\n', 1, NULL, '2026-07-13 15:21:39'),
(448, 4, 2, 'Ayam Kalasan', 'Resep Ayam Kalasan khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+kalasan\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan bawang putih, kemiri, dan kunyit.\n2. Lumuri ayam dengan bumbu halus dan gula merah.\n3. Rebus ayam dengan air kelapa dan daun salam hingga empuk.\n4. Biarkan air rebusan menyusut.\n5. Panaskan minyak, goreng ayam hingga kecoklatan.\n6. Angkat dan tiriskan.\n7. Sajikan ayam kalasan dengan nasi hangat dan lalapan.\n8. Ayam kalasan khas Jogja siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:39'),
(449, 5, 2, 'Ayam Kecap', 'Resep Ayam Kecap khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+kecap\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil, cuci bersih.\n2. Haluskan bawang merah, bawang putih, jahe, dan cabai merah.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan ayam, aduk hingga berubah warna.\n5. Tambahkan kecap manis dan merica bubuk.\n6. Beri sedikit air, masak hingga ayam empuk.\n7. Masukkan daun bawang iris, aduk sebentar.\n8. Koreksi rasa, angkat dan sajikan.\n', 1, NULL, '2026-07-13 15:21:39'),
(450, 6, 2, 'Ayam Geprek', 'Resep Ayam Geprek khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+geprek\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan bawang putih, garam, dan merika untuk marinasi.\n2. Lumuri ayam dengan bumbu, diamkan 15 menit.\n3. Campur tepung terigu dengan sedikit garam dan merica.\n4. Celupkan ayam ke kocokan telur, gulingkan di tepung.\n5. Goreng ayam dalam minyak panas hingga kuning kecoklatan.\n6. Angkat dan tiriskan.\n7. Haluskan cabai rawit dan bawang putih untuk sambal.\n8. Geprek ayam dengan ulekan, campur dengan sambal.\n9. Sajikan dengan nasi hangat dan lalapan.\n', 1, NULL, '2026-07-13 15:21:39'),
(451, 7, 2, 'Ayam Balado', 'Resep Ayam Balado khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+balado\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam, rebus hingga empuk lalu goreng hingga kecoklatan.\n2. Haluskan cabai merah, bawang merah, bawang putih, dan tomat.\n3. Panaskan minyak, tumis bumbu halus hingga harum.\n4. Tambahkan garam dan gula pasir.\n5. Masukkan ayam goreng, aduk rata dengan bumbu balado.\n6. Masak sebentar hingga bumbu meresap.\n7. Angkat dan sajikan.\n8. Ayam balado khas Padang siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:39'),
(452, 8, 2, 'Ayam Asam Manis', 'Resep Ayam Asam Manis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+asam+manis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam dadu, lumuri dengan garam dan merica.\n2. Celup ayam ke kocokan telur, gulingkan di tepung terigu.\n3. Goreng ayam hingga kuning kecoklatan, angkat.\n4. Potong nanas kecil-kecil, iris bawang bombay.\n5. Tumis bawang bombay hingga harum.\n6. Masukkan saus tomat, gula pasir, cuka, dan sedikit air.\n7. Masukkan nanas dan ayam goreng, aduk rata.\n8. Masak hingga saus mengental, angkat.\n9. Sajikan ayam asam manis dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(453, 4, 2, 'Ayam Kung Pao', 'Resep Ayam Kung Pao khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+kung+pao\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam dadu, marinasi dengan kecap asin dan jahe.\n2. Goreng ayam hingga matang, angkat.\n3. Sangrai kacang mede sebentar.\n4. Potong cabai merah kering atau segar.\n5. Tumis bawang putih cabai hingga harum.\n6. Masukkan ayam goreng, aduk rata.\n7. Tambahkan kecap asin, cuka, dan daun bawang.\n8. Masukkan kacang mede, aduk sebentar.\n9. Sajikan ayam kung pao dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(454, 5, 2, 'Ayam Cabai Hijau', 'Resep Ayam Cabai Hijau khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+cabai+hijau\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil, rebus setengah matang.\n2. Iris serong cabai hijau.\n3. Haluskan bawang merah, bawang putih, jahe.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan cabai hijau dan daun salam, aduk.\n6. Masukkan ayam, tambahkan garam dan gula.\n7. Beri sedikit air, masak hingga bumbu meresap.\n8. Angkat dan sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(455, 6, 2, 'Ayam Kari', 'Resep Ayam Kari khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+kari\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam menjadi beberapa bagian.\n2. Haluskan bawang merah, bawang putih, dan kunyit.\n3. Tumis bumbu halus dengan kari bubuk hingga harum.\n4. Masukkan daun salam dan sereh geprek.\n5. Masukkan ayam, aduk hingga berubah warna.\n6. Tuang santan, masak dengan api kecil.\n7. Aduk sesekali agar santan tidak pecah.\n8. Masak hingga ayam empuk dan kuah mengental.\n9. Sajikan ayam kari dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:39'),
(456, 7, 2, 'Ayam Suwir', 'Resep Ayam Suwir khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+suwir\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus ayam hingga empuk, suwir-suwir kasar.\n2. Haluskan cabai merah, bawang merah, bawang putih, dan kunyit.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan daun jeruk.\n5. Masukkan ayam suwir, aduk rata.\n6. Tambahkan garam dan gula pasir.\n7. Beri sedikit air, masak hingga bumbu meresap.\n8. Angkat dan sajikan.\n9. Ayam suwir cocok untuk isian nasi bakar atau nasi campur.\n', 1, NULL, '2026-07-13 15:21:39'),
(457, 8, 2, 'Ayam Bakar Madu', 'Resep Ayam Bakar Madu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+bakar+madu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan bawang putih dan jahe.\n2. Campur ayam dengan bumbu halus, madu, kecap, jeruk nipis, dan merica.\n3. Diamkan minimal 30 menit dalam kulkas.\n4. Panaskan panggangan atau oven.\n5. Bakar ayam sambil dioles sisa bumbu madu.\n6. Balik ayam dan oles bumbu secara berkala.\n7. Bakar hingga ayam matang kecoklatan.\n8. Angkat dan sajikan dengan nasi hangat.\n9. Ayam bakar madu cocok untuk acara spesial.\n', 1, NULL, '2026-07-13 15:21:40'),
(458, 4, 2, 'Ayam Cabe Ijo', 'Resep Ayam Cabe Ijo khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+cabe+ijo\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil, cuci bersih.\n2. Haluskan cabai hijau besar, bawang merah, bawang putih.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan daun jeruk.\n5. Masukkan ayam, aduk hingga berubah warna.\n6. Tambahkan garam, gula, dan santan.\n7. Masak hingga ayam empuk dan kuah mengental.\n8. Koreksi rasa, angkat.\n9. Sajikan ayam cabe ijo dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(459, 5, 2, 'Ayam Saus Padang', 'Resep Ayam Saus Padang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+saus+padang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Goreng ayam hingga setengah matang, angkat.\n2. Haluskan cabai merah, cabai rawit, bawang merah, bawang putih.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan saus tomat dan saus tiram.\n5. Tambahkan air, aduk rata.\n6. Masukkan ayam, masak hingga saus mengental.\n7. Masukkan daun bawang iris, aduk sebentar.\n8. Sajikan ayam saus padang dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(460, 6, 2, 'Ayam Mentega', 'Resep Ayam Mentega khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+mentega\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil, lumuri dengan garam dan merica.\n2. Goreng ayam hingga matang kecoklatan, angkat.\n3. Lelehkan margarin dalam wajan.\n4. Tumis bawang bombay hingga harum dan layu.\n5. Masukkan kecap manis dan kecap asin, aduk.\n6. Masukkan ayam goreng, aduk rata dengan saus.\n7. Tambahkan daun bawang iris, aduk sebentar.\n8. Sajikan ayam mentega dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(461, 7, 2, 'Ayam Bakar Pedas', 'Resep Ayam Bakar Pedas khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ayam+bakar+pedas\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Haluskan cabai rawit, cabai merah, bawang merah, bawang putih, dan terasi.\n2. Lumuri ayam dengan bumbu halus, tambahkan gula merah dan garam.\n3. Kucuri jeruk nipis, diamkan 30 menit.\n4. Panaskan panggangan atau grill.\n5. Bakar ayam sambil sesekali dioles sisa bumbu.\n6. Balik agar matang merata.\n7. Sajikan dengan lalapan dan nasi hangat.\n8. Ayam bakar pedas siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:40'),
(462, 8, 2, 'Ikan Gurame Asam Manis', 'Resep Ikan Gurame Asam Manis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+gurame+asam+manis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan gurame, kerat-kerat badannya, lumuri jeruk nipis dan garam.\n2. Goreng ikan dalam minyak panas hingga kuning kecoklatan dan kering.\n3. Angkat dan tiriskan, sisihkan.\n4. Iris bawang bombay dan nanas kecil-kecil.\n5. Tumis bawang bombay hingga harum dan layu.\n6. Masukkan saus tomat, cuka, gula pasir, dan sedikit air, aduk rata.\n7. Masukkan nanas, masak hingga saus mengental.\n8. Masukkan ikan goreng, aduk perlahan dengan saus.\n9. Taburi daun bawang, sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(463, 4, 2, 'Ikan Bawal Bakar', 'Resep Ikan Bawal Bakar khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+bawal+bakar\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan bawal, kerat-kerat badannya.\n2. Haluskan bawang putih, jahe, kunyit, dan cabai merah.\n3. Lumuri ikan dengan bumbu halus, kecap manis, dan jeruk nipis.\n4. Diamkan 20 menit agar bumbu meresap.\n5. Panaskan panggangan atau grill.\n6. Bakar ikan bawal sambil dioles sisa bumbu.\n7. Balik ikan agar matang merata.\n8. Sajikan dengan sambal dan lalapan segar.\n', 1, NULL, '2026-07-13 15:21:40'),
(464, 5, 2, 'Ikan Tenggiri Balado', 'Resep Ikan Tenggiri Balado khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+tenggiri+balado\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ikan tenggiri menjadi beberapa bagian.\n2. Lumuri dengan garam dan jeruk nipis, diamkan sebentar.\n3. Goreng ikan hingga matang kecoklatan, angkat.\n4. Haluskan cabai merah, bawang merah, bawang putih, dan tomat.\n5. Tumis bumbu halus hingga harum dan matang.\n6. Tambahkan garam dan gula pasir, aduk rata.\n7. Masukkan ikan tenggiri goreng, aduk dengan bumbu balado.\n8. Sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(465, 6, 2, 'Ikan Kuah Kuning', 'Resep Ikan Kuah Kuning khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+kuah+kuning\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan mas, lumuri dengan jeruk nipis dan garam.\n2. Haluskan bawang merah, bawang putih, kunyit, dan jahe.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan sereh geprek dan daun salam.\n5. Tambahkan air, didihkan.\n6. Masukkan ikan mas, masak dengan api kecil.\n7. Beri garam, koreksi rasa.\n8. Masak hingga ikan matang dan kuah menguning.\n9. Sajikan ikan kuah kuning dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(466, 7, 2, 'Ikan Cakalang Suwir', 'Resep Ikan Cakalang Suwir khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+cakalang+suwir\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kukus atau rebus ikan cakalang hingga matang.\n2. Suwir-suwir daging ikan, buang durinya.\n3. Haluskan cabai merah, bawang merah, bawang putih, dan kunyit.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan daun jeruk sobek-sobek.\n6. Masukkan ikan cakalang suwir, aduk rata.\n7. Tambahkan garam, masak hingga bumbu meresap.\n8. Sajikan dengan nasi hangat.\n9. Ikan cakalang suwir khas Manado siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:40'),
(467, 8, 2, 'Ikan Baronang Bakar', 'Resep Ikan Baronang Bakar khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+baronang+bakar\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan baronang, kerat-kerat badannya.\n2. Haluskan bawang putih, jahe, kunyit, dan cabai rawit.\n3. Lumuri ikan dengan bumbu halus, kecap manis, dan jeruk nipis.\n4. Diamkan 20 menit agar bumbu meresap.\n5. Panaskan panggangan atau grill.\n6. Bakar ikan sambil dioles sisa bumbu.\n7. Balik ikan agar matang sempurna.\n8. Sajikan dengan sambal dabu-dabu dan lalapan.\n', 1, NULL, '2026-07-13 15:21:40'),
(468, 4, 2, 'Ikan Kakap Saus Padang', 'Resep Ikan Kakap Saus Padang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+kakap+saus+padang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Fillet ikan kakap, potong-potong, lumuri garam dan jeruk nipis.\n2. Goreng ikan hingga matang kecoklatan, angkat.\n3. Haluskan cabai merah, cabai rawit, bawang merah, dan bawang putih.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan saus tomat dan saus tiram, tambahkan air sedikit.\n6. Masak hingga saus mendidih dan mengental.\n7. Masukkan ikan kakap goreng, aduk rata dengan saus.\n8. Taburi daun bawang, sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(469, 5, 2, 'Ikan Rica-rica', 'Resep Ikan Rica-rica khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+rica-rica\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan mas, potong-potong, lumuri garam dan jeruk nipis.\n2. Goreng ikan hingga setengah matang, angkat.\n3. Haluskan cabai rawit, bawang merah, bawang putih, dan jahe.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan daun jeruk dan sereh geprek.\n6. Tambahkan air, masukkan ikan, masak hingga matang.\n7. Beri garam, koreksi rasa.\n8. Sajikan ikan rica-rica dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(470, 6, 2, 'Ikan Woku Belanga', 'Resep Ikan Woku Belanga khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+woku+belanga\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ikan patin menjadi beberapa bagian, cuci bersih.\n2. Haluskan cabai rawit, bawang merah, bawang putih, dan kunyit.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan daun jeruk sobek-sobek.\n5. Masukkan ikan patin, aduk perlahan.\n6. Tambahkan air, masak hingga ikan matang.\n7. Masukkan kemangi, aduk sebentar hingga layu.\n8. Koreksi rasa, angkat dan sajikan.\n', 1, NULL, '2026-07-13 15:21:40'),
(471, 7, 2, 'Ikan Bakar Acar', 'Resep Ikan Bakar Acar khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+bakar+acar\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan nila, kerat-kerat, lumuri garam dan jeruk nipis.\n2. Haluskan bawang putih dan kunyit, lumuri ke ikan.\n3. Bakar ikan di atas panggangan hingga matang kecoklatan.\n4. Buat acar: iris timun, wortel, bawang merah, dan cabai merah.\n5. Campur sayuran dengan cuka, gula pasir, dan sedikit garam.\n6. Diamkan acar sebentar agar meresap.\n7. Sajikan ikan bakar dengan acar segar.\n8. Ikan bakar acar cocok sebagai hidangan makan siang.\n', 1, NULL, '2026-07-13 15:21:40'),
(472, 8, 2, 'Ikan Bumbu Kuning', 'Resep Ikan Bumbu Kuning khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+bumbu+kuning\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan bandeng, potong-potong.\n2. Haluskan kunyit, bawang putih, kemiri, jahe, dan garam.\n3. Lumuri ikan dengan bumbu halus.\n4. Panaskan minyak, tumis bumbu sisa bersama daun salam dan sereh.\n5. Masukkan ikan, tambahkan air.\n6. Masak dengan api kecil hingga ikan matang dan bumbu meresap.\n7. Koreksi rasa, angkat.\n8. Sajikan ikan bumbu kuning dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(473, 4, 2, 'Ikan Kembung Goreng', 'Resep Ikan Kembung Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+kembung+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan kembung, buang insang dan isi perut.\n2. Lumuri ikan dengan garam, bawang putih halus, kunyit, dan jahe.\n3. Kucuri jeruk nipis, diamkan 15 menit.\n4. Panaskan minyak dalam wajan.\n5. Goreng ikan kembung hingga matang kecoklatan.\n6. Balik sekali agar matang merata.\n7. Angkat dan tiriskan.\n8. Sajikan dengan nasi hangat dan sambal terasi.\n', 1, NULL, '2026-07-13 15:21:40'),
(474, 5, 2, 'Ikan Patin Kuah Kuning', 'Resep Ikan Patin Kuah Kuning khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+patin+kuah+kuning\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ikan patin, cuci bersih, lumuri jeruk nipis.\n2. Haluskan bawang merah, bawang putih, kunyit, dan jahe.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan sereh geprek dan daun jeruk.\n5. Tambahkan air, didihkan.\n6. Masukkan ikan patin, masak dengan api kecil.\n7. Beri garam, koreksi rasa.\n8. Masak hingga ikan matang dan kuah menguning.\n9. Sajikan selagi hangat dengan nasi.\n', 1, NULL, '2026-07-13 15:21:40'),
(475, 6, 2, 'Udang Saus Padang', 'Resep Udang Saus Padang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+udang+saus+padang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas udang, buang kepala, cuci bersih.\n2. Haluskan cabai merah, bawang merah, dan bawang putih.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan saus tomat dan saus tiram, aduk rata.\n5. Tambahkan air sedikit, masak hingga mendidih.\n6. Masukkan udang, masak hingga berubah warna.\n7. Kocok lepas telur, masukkan ke saus sambil diaduk cepat.\n8. Taburi daun bawang, sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40');
INSERT INTO `resep` (`id`, `id_user`, `id_kategori`, `judul`, `deskripsi`, `langkah_memasak`, `jumlah_porsi`, `foto`, `created_at`) VALUES
(476, 7, 2, 'Udang Balado', 'Resep Udang Balado khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+udang+balado\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas udang, cuci bersih, goreng sebentar hingga kemerahan.\n2. Haluskan cabai merah, bawang merah, bawang putih, dan tomat.\n3. Tumis bumbu halus hingga harum dan matang.\n4. Tambahkan garam dan gula pasir.\n5. Masukkan udang goreng, aduk rata dengan bumbu balado.\n6. Masak sebentar hingga bumbu meresap.\n7. Angkat dan sajikan.\n8. Udang balado khas Padang siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:40'),
(477, 8, 2, 'Udang Asam Manis', 'Resep Udang Asam Manis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+udang+asam+manis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas udang, buang kepala, cuci bersih.\n2. Goreng udang sebentar hingga berubah warna, angkat.\n3. Iris bawang bombay dan bawang putih.\n4. Tumis bawang bombay dan bawang putih dengan jahe hingga harum.\n5. Masukkan saus tomat, cuka, gula pasir, dan sedikit air.\n6. Masak hingga saus mendidih dan mengental.\n7. Masukkan udang, aduk rata dengan saus.\n8. Taburi daun bawang, sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(478, 4, 2, 'Cumi Hitam', 'Resep Cumi Hitam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cumi+hitam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan cumi, jangan buang tinta hitamnya.\n2. Potong cumi bentuk cincin, lumuri jeruk nipis.\n3. Haluskan bawang merah, bawang putih, cabai merah, dan jahe.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan cumi beserta tintanya, aduk rata.\n6. Tambahkan garam dan gula pasir.\n7. Masak dengan api besar sebentar saja agar cumi tidak alot.\n8. Sajikan cumi hitam dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(479, 5, 2, 'Cumi Saus Padang', 'Resep Cumi Saus Padang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cumi+saus+padang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan cumi, potong cincin, cuci bersih.\n2. Goreng cumi sebentar, angkat dan tiriskan.\n3. Haluskan cabai merah, bawang merah, dan bawang putih.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan saus tomat dan saus tiram.\n6. Tambahkan air, masak hingga mendidih.\n7. Masukkan cumi, aduk rata, masak sebentar.\n8. Taburi daun bawang, sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(480, 6, 2, 'Cumi Goreng Tepung', 'Resep Cumi Goreng Tepung khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cumi+goreng+tepung\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan cumi, potong cincin, lumuri jeruk nipis dan garam.\n2. Campur tepung terigu, tepung beras, garam, dan merica.\n3. Kocok telur, celupkan cumi ke telur.\n4. Gulingkan cumi di campuran tepung hingga terbalut rata.\n5. Panaskan minyak dalam wajan.\n6. Goreng cumi dalam minyak panas hingga kuning keemasan.\n7. Angkat dan tiriskan.\n8. Sajikan dengan saus sambal atau mayones.\n', 1, NULL, '2026-07-13 15:21:40'),
(481, 7, 2, 'Kepiting Saus Padang', 'Resep Kepiting Saus Padang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kepiting+saus+padang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan kepiting, sikat cangkang, potong menjadi dua.\n2. Kukus atau rebus kepiting hingga matang, sisihkan.\n3. Haluskan cabai merah, bawang merah, dan bawang putih.\n4. Tumis bumbu halus hingga harum.\n5. Masukkan saus tomat dan saus tiram.\n6. Tambahkan air, masak hingga mendidih.\n7. Kocok telur, masukkan ke saus sambil diaduk.\n8. Masukkan kepiting, aduk rata dengan saus.\n9. Taburi daun bawang, sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(482, 8, 2, 'Kepiting Lada Hitam', 'Resep Kepiting Lada Hitam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kepiting+lada+hitam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan kepiting, potong, kukus hingga matang.\n2. Tumbuk kasar lada hitam.\n3. Cincang bawang bombay dan bawang putih.\n4. Lelehkan margarin, tumis bawang bombay dan bawang putih hingga harum.\n5. Masukkan lada hitam, kecap manis, dan kecap asin.\n6. Tambahkan air sedikit, masak hingga mengental.\n7. Masukkan kepiting, aduk rata dengan saus.\n8. Taburi daun bawang, sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(483, 4, 2, 'Kerang Hijau Saus Tiram', 'Resep Kerang Hijau Saus Tiram khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kerang+hijau+saus+tiram\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan kerang hijau, rebus hingga cangkang terbuka.\n2. Tiriskan kerang, buka cangkang, ambil dagingnya.\n3. Cincang bawang putih dan jahe, iris cabai merah.\n4. Tumis bawang putih dan jahe hingga harum.\n5. Masukkan cabai merah, aduk sebentar.\n6. Masukkan saus tiram dan merica bubuk.\n7. Masukkan daging kerang, aduk rata, masak sebentar.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(484, 5, 2, 'Kerang Dara Rebus', 'Resep Kerang Dara Rebus khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kerang+dara+rebus\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan kerang dara, cuci hingga air cucian bersih.\n2. Didihkan air dalam panci.\n3. Masukkan bawang putih geprek, jahe, sereh, dan daun jeruk.\n4. Masukkan kerang dara, rebus hingga semua cangkang terbuka.\n5. Angkat dan tiriskan.\n6. Sajikan dengan sambal kecap dari cabai rawit, kecap manis, dan jeruk nipis.\n7. Kerang dara rebus siap dinikmati sebagai camilan atau lauk.\n', 1, NULL, '2026-07-13 15:21:40'),
(485, 6, 2, 'Ikan Bandeng Presto', 'Resep Ikan Bandeng Presto khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+bandeng+presto\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan bandeng, buang insang dan isi perut.\n2. Haluskan bawang putih, kunyit, jahe, dan garam.\n3. Lumuri ikan dengan bumbu halus hingga rata.\n4. Masukkan daun salam dan sereh ke dalam perut ikan.\n5. Masak dalam panci presto selama 30-45 menit hingga duri empuk.\n6. Setelah matang, angkat dan tiriskan.\n7. Goreng ikan sebentar jika suka tekstur lebih kering.\n8. Sajikan dengan nasi hangat dan sambal.\n', 1, NULL, '2026-07-13 15:21:40'),
(486, 7, 2, 'Ikan Lele Goreng Sambal', 'Resep Ikan Lele Goreng Sambal khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ikan+lele+goreng+sambal\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan lele, lumuri jeruk nipis dan garam.\n2. Haluskan bawang putih dan kunyit, lumuri ke ikan lele.\n3. Diamkan 15 menit agar bumbu meresap.\n4. Goreng ikan lele dalam minyak panas hingga kecoklatan.\n5. Angkat dan tiriskan.\n6. Haluskan cabai rawit, cabai merah, terasi, dan garam untuk sambal.\n7. Siram sambal dengan minyak panas sisa gorengan.\n8. Sajikan ikan lele dengan sambal dan lalapan.\n', 1, NULL, '2026-07-13 15:21:40'),
(487, 8, 2, 'Semur Daging Sapi', 'Resep Semur Daging Sapi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+semur+daging+sapi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong daging sapi ukuran dadu, cuci bersih.\n2. Haluskan bawang merah, bawang putih, kemiri, jahe, dan gula merah.\n3. Tumis bumbu halus hingga harum, masukkan daun salam.\n4. Masukkan daging sapi, aduk hingga berubah warna.\n5. Tambahkan kecap manis, aduk rata.\n6. Tuang air hingga daging terendam, masak dengan api kecil.\n7. Masak hingga daging empuk dan kuah mengental.\n8. Koreksi rasa, angkat dan sajikan.\n9. Semur daging sapi cocok disantap dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(488, 4, 2, 'Daging Bumbu Bali', 'Resep Daging Bumbu Bali khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+daging+bumbu+bali\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging sapi hingga empuk, potong dadu.\n2. Goreng daging sebentar, sisihkan.\n3. Haluskan cabai merah, bawang merah, bawang putih, kemiri, kunyit, dan jahe.\n4. Tumis bumbu halus hingga harum dan matang.\n5. Masukkan daging, aduk rata.\n6. Tambahkan gula merah, garam, dan sedikit air.\n7. Masak hingga bumbu meresap dan mengering.\n8. Sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(489, 5, 2, 'Tongseng Sapi', 'Resep Tongseng Sapi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tongseng+sapi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong daging sapi tipis-tipis, iris kol dan tomat.\n2. Haluskan bawang merah, bawang putih, dan cabai merah.\n3. Tumis bumbu halus hingga harum.\n4. Masukkan daging sapi, aduk hingga berubah warna.\n5. Tambahkan kecap manis dan sedikit air.\n6. Masukkan kol dan tomat, aduk rata.\n7. Masak hingga sayuran layu dan daging matang.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(490, 6, 2, 'Empal Gepuk', 'Resep Empal Gepuk khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+empal+gepuk\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging sapi hingga setengah empuk, iris tipis melebar.\n2. Haluskan bawang putih, kemiri, kunyit, dan garam.\n3. Lumuri daging dengan bumbu halus, tambahkan gula merah.\n4. Masukkan daun salam dan sereh geprek, kukus hingga empuk.\n5. Pukul-pukul daging hingga melebar dan pipih.\n6. Goreng dalam minyak panas hingga kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan empal gepuk dengan nasi hangat dan sambal.\n', 1, NULL, '2026-07-13 15:21:40'),
(491, 7, 2, 'Sapi Lada Hitam', 'Resep Sapi Lada Hitam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sapi+lada+hitam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong daging sapi tipis melebar, lumuri kecap asin dan lada hitam.\n2. Tumbuk kasar lada hitam.\n3. Lelehkan margarin, tumis bawang bombay dan bawang putih hingga harum.\n4. Masukkan daging sapi, masak hingga berubah warna.\n5. Tambahkan kecap manis dan lada hitam tumbuk.\n6. Beri sedikit air, masak hingga daging empuk.\n7. Masukkan daun bawang, aduk sebentar.\n8. Sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:40'),
(492, 8, 2, 'Kari Kambing', 'Resep Kari Kambing khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kari+kambing\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong daging kambing ukuran dadu, cuci bersih.\n2. Haluskan bawang merah, bawang putih, dan kunyit.\n3. Tumis bumbu halus dengan kari bubuk hingga harum.\n4. Masukkan daun salam dan sereh geprek.\n5. Masukkan daging kambing, aduk hingga berubah warna.\n6. Tuang santan, masak dengan api kecil.\n7. Aduk sesekali, masak hingga daging empuk.\n8. Koreksi rasa, sajikan dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(493, 4, 2, 'Gulai Nangka', 'Resep Gulai Nangka khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+gulai+nangka\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong nangka muda, rebus hingga setengah empuk, tiriskan.\n2. Haluskan bawang merah, bawang putih, cabai merah, kunyit, dan jahe.\n3. Tumis bumbu halus hingga harum, masukkan daun salam.\n4. Masukkan nangka, aduk rata.\n5. Tuang santan, masak dengan api kecil.\n6. Aduk sesekali agar santan tidak pecah.\n7. Masak hingga nangka empuk dan kuah mengental.\n8. Koreksi rasa, sajikan gulai nangka selagi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(494, 5, 2, 'Lodeh Terong', 'Resep Lodeh Terong khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lodeh+terong\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong terong, labu siam, dan kacang panjang sesuai selera.\n2. Haluskan bawang merah, bawang putih, dan cabai merah.\n3. Tumis bumbu halus hingga harum, masukkan daun salam.\n4. Masukkan sayuran keras (labu siam) terlebih dahulu.\n5. Tambahkan air, masak hingga setengah matang.\n6. Tuang santan, aduk perlahan.\n7. Masukkan terong dan kacang panjang, masak hingga matang.\n8. Koreksi rasa, sajikan lodeh terong selagi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(495, 6, 2, 'Sayur Asem', 'Resep Sayur Asem khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sayur+asem\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong kacang panjang, labu siam, dan jagung manis.\n2. Didihkan air dalam panci.\n3. Masukkan jagung dan labu siam, rebus hingga empuk.\n4. Haluskan bawang merah dan garam.\n5. Masukkan bumbu halus, daun salam, dan asam Jawa.\n6. Tambahkan gula merah.\n7. Masukkan kacang panjang, masak sebentar.\n8. Terakhir masukkan bayam, masak sebentar hingga layu.\n9. Koreksi rasa, sajikan sayur asem hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(496, 7, 2, 'Tahu Bacem', 'Resep Tahu Bacem khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+bacem\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih agak tebal, goreng sebentar hingga berkulit.\n2. Haluskan bawang putih, kemiri, ketumbar, dan garam.\n3. Didihkan air, masukkan bumbu halus, gula merah, dan daun salam.\n4. Masukkan tahu, masak dengan api kecil.\n5. Biarkan hingga bumbu meresap dan air menyusut.\n6. Panaskan minyak, goreng tahu bacem sebentar.\n7. Angkat dan tiriskan.\n8. Sajikan tahu bacem dengan nasi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(497, 8, 2, 'Tempe Bacem', 'Resep Tempe Bacem khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tempe+bacem\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tempe agak tebal, kerat-kerat permukaannya.\n2. Haluskan bawang putih, kemiri, ketumbar, dan garam.\n3. Didihkan air, masukkan bumbu halus, gula merah, dan daun salam.\n4. Masukkan tempe, masak dengan api kecil.\n5. Biarkan hingga bumbu meresap dan air menyusut.\n6. Panaskan minyak, goreng tempe bacem hingga kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan tempe bacem sebagai lauk pendamping.\n', 1, NULL, '2026-07-13 15:21:41'),
(498, 4, 2, 'Tahu Gejrot', 'Resep Tahu Gejrot khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+gejrot\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih kotak-kotak kecil.\n2. Goreng tahu hingga kecoklatan, angkat dan tiriskan.\n3. Iris tipis bawang merah dan cabai rawit.\n4. Larutkan gula merah dengan sedikit air hangat, tambahkan asam Jawa.\n5. Masukkan irisan bawang merah, cabai rawit, dan kecap manis.\n6. Aduk rata bumbu gejrot.\n7. Letakkan tahu goreng di piring, siram dengan bumbu gejrot.\n8. Taburi daun bawang, sajikan.\n', 1, NULL, '2026-07-13 15:21:41'),
(499, 5, 2, 'Sayur Lodeh', 'Resep Sayur Lodeh khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sayur+lodeh\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong labu siam, terong, dan kacang panjang.\n2. Haluskan bawang merah, bawang putih, dan cabai merah.\n3. Tumis bumbu halus hingga harum, masukkan daun salam.\n4. Masukkan labu siam, aduk, tambahkan air.\n5. Masak hingga labu siam setengah empuk.\n6. Tuang santan, aduk perlahan.\n7. Masukkan terong dan kacang panjang, masak hingga matang.\n8. Koreksi rasa, sajikan sayur lodeh hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(500, 6, 2, 'Oseng Kacang Panjang', 'Resep Oseng Kacang Panjang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+oseng+kacang+panjang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong kacang panjang sepanjang 3 cm.\n2. Iris tipis bawang merah, bawang putih, dan cabai merah.\n3. Panaskan minyak, tumis bawang merah dan bawang putih hingga harum.\n4. Masukkan cabai merah, aduk sebentar.\n5. Masukkan kacang panjang, aduk rata.\n6. Tambahkan garam dan gula pasir.\n7. Beri sedikit air, masak hingga kacang panjang matang.\n8. Angkat dan sajikan sebagai lauk pendamping.\n', 1, NULL, '2026-07-13 15:21:41'),
(501, 7, 2, 'Tumis Buncis', 'Resep Tumis Buncis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tumis+buncis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan buncis, potong serong tipis.\n2. Iris bawang merah, bawang putih, dan cabai merah.\n3. Panaskan minyak, tumis bawang merah dan bawang putih hingga harum.\n4. Masukkan cabai merah, aduk sebentar.\n5. Masukkan buncis, aduk rata.\n6. Tambahkan garam dan gula pasir.\n7. Beri sedikit air, masak hingga buncis matang namun tetap renyah.\n8. Taburi daun bawang, sajikan.\n', 1, NULL, '2026-07-13 15:21:41'),
(502, 8, 2, 'Tumis Bayam', 'Resep Tumis Bayam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tumis+bayam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan bayam, petik daunnya, cuci bersih.\n2. Cincang bawang putih dan iris daun bawang.\n3. Panaskan minyak, tumis bawang putih hingga harum.\n4. Masukkan bayam, aduk cepat.\n5. Tambahkan garam dan merica bubuk.\n6. Masukkan daun bawang, aduk hingga bayam layu.\n7. Angkat dan sajikan segera.\n', 1, NULL, '2026-07-13 15:21:41'),
(503, 4, 2, 'Tumis Labu Siam', 'Resep Tumis Labu Siam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tumis+labu+siam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas labu siam, potong korek api, cuci bersih.\n2. Iris bawang merah, bawang putih, dan cabai merah.\n3. Panaskan minyak, tumis bawang merah dan bawang putih hingga harum.\n4. Masukkan cabai merah, aduk sebentar.\n5. Masukkan labu siam, aduk rata.\n6. Tambahkan garam, beri sedikit air.\n7. Masak hingga labu siam matang dan empuk.\n8. Taburi daun bawang, sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(504, 5, 2, 'Cah Brokoli', 'Resep Cah Brokoli khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cah+brokoli\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong buncis serong, iris wortel tipis.\n2. Cincang bawang putih dan jahe.\n3. Panaskan minyak, tumis bawang putih dan jahe hingga harum.\n4. Masukkan wortel, aduk sebentar.\n5. Masukkan buncis, aduk rata.\n6. Tambahkan garam dan merica bubuk.\n7. Tuang sedikit air, masak hingga sayuran matang namun tetap renyah.\n8. Angkat dan sajikan.\n', 1, NULL, '2026-07-13 15:21:41'),
(505, 6, 2, 'Cah Jagung Muda', 'Resep Cah Jagung Muda khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cah+jagung+muda\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong jagung muda serong tipis-tipis.\n2. Cincang bawang putih.\n3. Panaskan minyak, tumis bawang putih hingga harum.\n4. Masukkan jagung muda, aduk rata.\n5. Tambahkan garam dan merica bubuk.\n6. Beri sedikit air, masak hingga matang.\n7. Taburi daun bawang, angkat dan sajikan.\n', 1, NULL, '2026-07-13 15:21:41'),
(506, 7, 2, 'Cah Sawi Putih', 'Resep Cah Sawi Putih khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cah+sawi+putih\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong sawi hijau ukuran 3 cm, cuci bersih.\n2. Cincang bawang putih.\n3. Panaskan minyak, tumis bawang putih hingga harum.\n4. Masukkan sawi hijau, aduk cepat.\n5. Tambahkan garam dan gula pasir.\n6. Beri sedikit air, masak hingga sawi layu.\n7. Taburi daun bawang, angkat dan sajikan.\n', 1, NULL, '2026-07-13 15:21:41'),
(507, 8, 2, 'Nasi Liwet', 'Resep Nasi Liwet khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+liwet\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Cuci beras hingga bersih, masukkan ke panci.\n2. Iris bawang merah dan bawang putih.\n3. Tumis bawang hingga harum, masukkan daun salam dan sereh.\n4. Masukkan tumisan ke dalam panci berisi beras.\n5. Tambahkan santan, air, dan garam.\n6. Masak dengan api kecil hingga air terserap.\n7. Kukus atau lanjutkan masak hingga matang sempurna.\n8. Sajikan nasi liwet dengan lauk pelengkap.\n', 1, NULL, '2026-07-13 15:21:41'),
(508, 4, 2, 'Nasi Kuning', 'Resep Nasi Kuning khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+kuning\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Cuci beras hingga bersih.\n2. Parut kunyit, peras airnya atau gunakan kunyit bubuk.\n3. Campur santan, air kunyit, garam, daun salam, dan sereh.\n4. Masukkan campuran ke beras, masak hingga air terserap.\n5. Kukus beras hingga matang sempurna.\n6. Aduk nasi agar tercampur rata.\n7. Sajikan nasi kuning dengan lauk pauk.\n', 1, NULL, '2026-07-13 15:21:41'),
(509, 5, 2, 'Nasi Tumpeng', 'Resep Nasi Tumpeng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+tumpeng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat nasi kuning seperti resep nasi kuning.\n2. Bentuk nasi kuning menjadi kerucut menggunakan cetakan tumpeng.\n3. Siapkan lauk: goreng telur, tempe, dan tahu.\n4. Siapkan sambal dan lalapan.\n5. Tata lauk di sekeliling nasi tumpeng.\n6. Hias dengan sayuran segar dan kerupuk.\n7. Sajikan untuk acara syukuran atau selamatan.\n', 1, NULL, '2026-07-13 15:21:41'),
(510, 6, 2, 'Nasi Pecel', 'Resep Nasi Pecel khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+pecel\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus kangkung, bayam, dan toge hingga matang, tiriskan.\n2. Goreng kacang tanah hingga matang.\n3. Haluskan kacang tanah goreng, cabai rawit, terasi, dan gula merah.\n4. Tambahkan air hangat ke bumbu pecel hingga kekentalan yang diinginkan.\n5. Letakkan nasi di piring, tata sayuran di sekelilingnya.\n6. Siram bumbu pecel di atas sayuran.\n7. Taburi bawang goreng dan kerupuk.\n8. Sajikan nasi pecel dengan lauk tambahan seperti tempe.\n', 1, NULL, '2026-07-13 15:21:41'),
(511, 7, 2, 'Nasi Bakar', 'Resep Nasi Bakar khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+bakar\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Tumis bawang merah dan bawang putih hingga harum.\n2. Masukkan cabai merah dan daging ayam cincang, masak hingga matang.\n3. Campur tumisan dengan nasi putih dan kemangi, aduk rata.\n4. Siapkan daun pisang, layukan di atas api sebentar.\n5. Letakkan nasi di atas daun pisang, bungkus rapi.\n6. Semat kedua ujungnya dengan lidi.\n7. Bakar di atas panggangan hingga daun pisang kecoklatan.\n8. Sajikan nasi bakar selagi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(512, 8, 2, 'Nasi Megono', 'Resep Nasi Megono khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+megono\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong nangka muda kecil-kecil, rebus hingga empuk.\n2. Parut kelapa, sangrai sebentar.\n3. Haluskan bawang merah, bawang putih, kunyit, dan cabai merah.\n4. Campur nangka rebus dengan bumbu halus dan kelapa parut.\n5. Kukus campuran nangka selama 15 menit.\n6. Sajikan nasi dengan megono di atasnya.\n7. Lengkapi dengan lauk seperti telur goreng dan sambal.\n8. Nasi megono khas Pekalongan siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:41'),
(513, 4, 2, 'Nasi Jamblang', 'Resep Nasi Jamblang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+jamblang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bungkus nasi putih dengan daun jati, tekan-tekan hingga padat.\n2. Goreng tempe dan tahu hingga kecoklatan.\n3. Siapkan sambal goreng atau lauk pelengkap lainnya.\n4. Buka bungkusan nasi jamblang di piring.\n5. Tata tempe goreng, tahu goreng, dan lauk lainnya.\n6. Tambahkan sambal dan lalapan.\n7. Nasi jamblang khas Cirebon siap disantap.\n', 1, NULL, '2026-07-13 15:21:41'),
(514, 5, 2, 'Nasi Ulam', 'Resep Nasi Ulam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+ulam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Parut kelapa, sangrai hingga setengah kering.\n2. Iris tipis bawang merah dan cabai rawit.\n3. Campur nasi putih dengan kelapa sangrai.\n4. Tambahkan bawang merah, cabai rawit, dan kemangi.\n5. Beri garam, aduk hingga semua tercampur rata.\n6. Sajikan nasi ulam dengan lauk gorengan.\n7. Nasi ulam khas Betawi siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:41'),
(515, 6, 2, 'Nasi Rames', 'Resep Nasi Rames khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+rames\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Goreng ayam, tempe, dan tahu hingga matang.\n2. Siapkan sayur lodeh dan sambal.\n3. Letakkan nasi di piring saji.\n4. Tata ayam goreng, tempe, tahu, dan sayur lodeh di sekeliling nasi.\n5. Tambahkan sambal dan taburan bawang goreng.\n6. Sajikan nasi rames selagi hangat.\n7. Nasi rames cocok untuk menu makan siang praktis.\n', 1, NULL, '2026-07-13 15:21:41'),
(516, 7, 2, 'Nasi Bakar Ayam', 'Resep Nasi Bakar Ayam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nasi+bakar+ayam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Suwir daging ayam yang sudah direbus.\n2. Tumis bawang merah dan bawang putih hingga harum.\n3. Masukkan cabai merah dan suwiran ayam.\n4. Campur tumisan ayam dengan nasi dan kemangi.\n5. Siapkan daun pisang, layukan sebentar.\n6. Bungkus nasi dengan daun pisang, semat lidi.\n7. Bakar di atas panggangan hingga daun pisang berbau harum.\n8. Sajikan nasi bakar ayam selagi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(517, 8, 2, 'Es Campur', 'Resep Es Campur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+campur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Serut es batu hingga halus, masukkan ke mangkuk saji.\n2. Potong alpukat, nanas, dan kelapa muda kecil-kecil.\n3. Potong roti tawar dadu kecil.\n4. Tata buah-buahan di atas es serut.\n5. Tambahkan roti tawar dan selasih yang sudah direndam.\n6. Siram dengan sirup merah dan susu kental manis.\n7. Aduk rata sebelum dinikmati.\n8. Es campur siap disajikan sebagai pencuci mulut.\n', 1, NULL, '2026-07-13 15:21:41'),
(518, 4, 2, 'Es Teler', 'Resep Es Teler khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+teler\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Serut es batu hingga halus.\n2. Potong alpukat, kelapa muda, dan nanas kotak-kotak.\n3. Potong cincau kecil-kecil.\n4. Tata semua bahan di dalam mangkuk.\n5. Siram dengan sirup dan susu kental manis.\n6. Tambahkan es serut di atasnya.\n7. Sajikan segera selagi dingin.\n8. Es teler khas Bali siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:41'),
(519, 5, 2, 'Es Buah', 'Resep Es Buah khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+buah\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Serut es batu, sisihkan.\n2. Potong semangka, melon, nanas, dan anggur kecil-kecil.\n3. Campur semua buah dalam mangkuk.\n4. Tambahkan es serut di atasnya.\n5. Siram dengan sirup dan susu kental manis.\n6. Aduk rata sebelum disajikan.\n7. Es buah segar siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:41'),
(520, 6, 2, 'Es Doger', 'Resep Es Doger khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+doger\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Serut es batu hingga halus.\n2. Potong alpukat, kelapa muda, dan tape singkong.\n3. Potong roti tawar dadu kecil.\n4. Tata semua bahan dalam mangkuk saji.\n5. Tambahkan es serut di atasnya.\n6. Siram dengan sirup merah dan susu kental manis.\n7. Sajikan segera selagi dingin.\n8. Es doger khas Bandung siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:41'),
(521, 7, 2, 'Es Cendol', 'Resep Es Cendol khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+cendol\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung beras, tepung tapioka, air daun suji, dan garam.\n2. Masak adonan hingga mengental, lalu saring dengan cetakan cendol.\n3. Tampung cendol dalam air es hingga mengeras.\n4. Rebus gula merah dengan sedikit air hingga mengental.\n5. Rebus santan dengan daun pandan dan sedikit garam.\n6. Siapkan mangkuk, masukkan cendol, siram dengan kuah santan.\n7. Tambahkan es serut dan kuah gula merah di atasnya.\n8. Es cendol siap dinikmati selagi dingin.\n', 1, NULL, '2026-07-13 15:21:41'),
(522, 8, 2, 'Es Dawet', 'Resep Es Dawet khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+dawet\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat cendol/dawet dari tepung beras dan air daun suji.\n2. Masak gula merah dengan sedikit air hingga kental.\n3. Rebus santan dengan garam hingga mendidih.\n4. Siapkan gelas saji, masukkan dawet.\n5. Tambahkan es serut.\n6. Siram dengan kuah gula merah dan santan.\n7. Sajikan es dawet selagi dingin.\n8. Es dawet khas Banjarnegara siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:41'),
(523, 4, 2, 'Es Lilin', 'Resep Es Lilin khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+lilin\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur susu kental manis, sirup, dan air dalam wadah.\n2. Aduk rata hingga tercampur sempurna.\n3. Tuang ke dalam cetakan es lilin.\n4. Masukkan stik es krim di tengahnya.\n5. Bekukan dalam freezer selama 6-8 jam hingga keras.\n6. Keluarkan dari cetakan dengan merendam sebentar di air hangat.\n7. Es lilin siap dinikmati sebagai camilan segar.\n', 1, NULL, '2026-07-13 15:21:41'),
(524, 5, 2, 'Es Krim Goreng', 'Resep Es Krim Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+krim+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Siapkan es krim dalam bentuk kotak atau bulat dari freezer.\n2. Balut es krim dengan tepung terigu tipis-tipis.\n3. Celupkan ke kocokan telur.\n4. Gulingkan di tepung roti hingga terbalut rata.\n5. Simpan dalam freezer selama 1 jam hingga keras.\n6. Panaskan minyak dalam wajan.\n7. Goreng es krim dalam minyak panas selama 10-15 detik saja.\n8. Angkat dan sajikan segera.\n', 1, NULL, '2026-07-13 15:21:41'),
(525, 6, 2, 'Puding Coklat', 'Resep Puding Coklat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+puding+coklat\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur agar-agar, gula pasir, dan coklat bubuk dalam panci.\n2. Tuang susu sapi, aduk rata.\n3. Masak dengan api sedang sambil terus diaduk.\n4. Tambahkan vanilla bubuk, aduk hingga mendidih.\n5. Angkat dan tuang ke cetakan puding.\n6. Biarkan suhu ruang, lalu dinginkan di kulkas.\n7. Sajikan puding coklat selagi dingin.\n8. Hias dengan parutan keju atau coklat sesuai selera.\n', 1, NULL, '2026-07-13 15:21:41'),
(526, 7, 2, 'Puding Buah', 'Resep Puding Buah khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+puding+buah\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong nanas, pepaya, dan anggur dadu kecil.\n2. Campur agar-agar, gula pasir, dan susu sapi dalam panci.\n3. Masak hingga mendidih sambil diaduk.\n4. Tata buah-buahan di dasar cetakan.\n5. Tuang agar-agar cair ke cetakan.\n6. Biarkan setengah mengeras, tambahkan buah lagi jika suka.\n7. Dinginkan di kulkas hingga set sempurna.\n8. Keluarkan dari cetakan dan sajikan.\n', 1, NULL, '2026-07-13 15:21:41'),
(527, 8, 2, 'Puding Lumut', 'Resep Puding Lumut khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+puding+lumut\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur agar-agar, gula pasir, santan, dan air daun suji.\n2. Kocok telur hingga berbusa, masukkan ke campuran agar-agar.\n3. Tambahkan vanilla bubuk, aduk rata.\n4. Masak dengan api kecil sambil terus diaduk.\n5. Telur akan membentuk gumpalan seperti lumut.\n6. Angkat setelah mendidih, tuang ke cetakan.\n7. Dinginkan hingga set.\n8. Sajikan puding lumut selagi dingin.\n', 1, NULL, '2026-07-13 15:21:41'),
(528, 4, 2, 'Puding Karamel', 'Resep Puding Karamel khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+puding+karamel\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Lelehkan gula pasir dalam panci hingga menjadi karamel keemasan.\n2. Tuang karamel ke dasar cetakan puding, ratakan.\n3. Campur agar-agar, sisa gula, susu sapi, dan telur kocok.\n4. Tambahkan vanilla bubuk, aduk rata.\n5. Masak hingga mendidih sambil diaduk.\n6. Tuang ke cetakan berlapis karamel.\n7. Dinginkan hingga set sempurna.\n8. Sajikan puding karamel dengan saus karamel di atasnya.\n', 1, NULL, '2026-07-13 15:21:41'),
(529, 5, 2, 'Bubur Sumsum', 'Resep Bubur Sumsum khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+bubur+sumsum\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung beras dengan santan dan air, aduk hingga larut.\n2. Masak dengan api kecil sambil terus diaduk.\n3. Tambahkan garam dan daun pandan.\n4. Masak hingga mengental dan matang, angkat.\n5. Rebus gula merah dengan sedikit air hingga mengental.\n6. Sajikan bubur sumsum dalam mangkuk.\n7. Siram dengan kuah gula merah di atasnya.\n8. Bubur sumsum siap dinikmati selagi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(530, 6, 2, 'Bubur Ketan Hitam', 'Resep Bubur Ketan Hitam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+bubur+ketan+hitam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Cuci beras ketan hitam, rendam semalaman.\n2. Rebus ketan hitam dengan air hingga empuk dan pecah.\n3. Tambahkan gula pasir dan daun pandan.\n4. Masak hingga menjadi bubur kental.\n5. Rebus santan dengan garam hingga mendidih.\n6. Sajikan bubur ketan hitam dalam mangkuk.\n7. Siram dengan kuah santan di atasnya.\n8. Bubur ketan hitam siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:41'),
(531, 7, 2, 'Klepon', 'Resep Klepon khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+klepon\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung ketan dengan air daun suji hingga hijau.\n2. Uleni hingga kalis.\n3. Isi adonan dengan potongan gula merah.\n4. Bentuk bulatan-bulatan kecil.\n5. Rebus dalam air mendidih hingga mengapung.\n6. Angkat dan tiriskan.\n7. Gulingkan klepon di atas kelapa parut yang sudah dikukus dengan garam.\n8. Sajikan klepon sebagai camilan manis.\n', 1, NULL, '2026-07-13 15:21:41'),
(532, 8, 2, 'Onde-onde', 'Resep Onde-onde khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+onde-onde\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung ketan dengan air, uleni hingga kalis.\n2. Haluskan kacang tanah goreng dengan gula pasir untuk isian.\n3. Ambil adonan, pipihkan, isi dengan kacang manis.\n4. Bentuk bulat, gulingkan di wijen hingga terbalut rata.\n5. Panaskan minyak dengan api kecil.\n6. Goreng onde-onde hingga kuning kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan onde-onde selagi hangat.\n', 1, NULL, '2026-07-13 15:21:41'),
(533, 4, 2, 'Kue Lapis', 'Resep Kue Lapis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+lapis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung beras, tepung tapioka, gula pasir, dan garam.\n2. Tuang santan sedikit demi sedikit sambil diaduk.\n3. Saring adonan hingga halus, bagi menjadi dua bagian.\n4. Satu bagian beri pasta pandan, satu bagian biarkan putih.\n5. Panaskan kukusan, oles loyang dengan minyak.\n6. Tuang adonan hijau tipis, kukus 5 menit hingga set.\n7. Tuang adonan putih tipis, kukus lagi 5 menit.\n8. Ulangi hingga adonan habis, kukus terakhir 15 menit.\n9. Potong setelah dingin, sajikan.\n', 1, NULL, '2026-07-13 15:21:41'),
(534, 5, 2, 'Kue Cubit', 'Resep Kue Cubit khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+cubit\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kocok telur dan gula pasir hingga mengembang.\n2. Masukkan tepung terigu, susu sapi, dan vanilla bubuk.\n3. Aduk rata hingga adonan licin.\n4. Panaskan cetakan kue cubit dengan margarin.\n5. Tuang adonan setengah cetakan.\n6. Taburi dengan coklat bubuk atau meses.\n7. Tutup dan masak hingga matang.\n8. Angkat dan sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(535, 6, 2, 'Kue Pancong', 'Resep Kue Pancong khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+pancong\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung terigu, tepung beras, gula pasir, dan garam.\n2. Tuang santan sedikit demi sedikit, aduk hingga licin.\n3. Diamkan adonan selama 15 menit.\n4. Panaskan cetakan kue pancong, oles dengan minyak.\n5. Tuang adonan ke cetakan hingga penuh.\n6. Masak dengan api kecil hingga matang kecoklatan.\n7. Angkat dan sajikan hangat.\n8. Kue pancong khas Betawi siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(536, 7, 2, 'Kue Pukis', 'Resep Kue Pukis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+pukis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kocok telur dan gula pasir hingga mengembang.\n2. Masukkan tepung terigu bergantian dengan santan.\n3. Tambahkan margarin cair dan vanilla bubuk, aduk rata.\n4. Diamkan adonan 30 menit.\n5. Panaskan cetakan pukis, oles minyak.\n6. Tuang adonan ke cetakan, taburi topping keju.\n7. Tutup dan masak hingga matang.\n8. Angkat dan sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(537, 8, 2, 'Kue Rangin', 'Resep Kue Rangin khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+rangin\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung beras, garam, dan gula pasir.\n2. Tuang santan sedikit demi sedikit, aduk hingga licin.\n3. Panaskan cetakan kue rangin, oles dengan minyak.\n4. Tuang adonan ke cetakan.\n5. Masak hingga pinggirnya kering dan kecoklatan.\n6. Angkat dan sajikan hangat.\n7. Kue rangin khas Betawi siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(538, 4, 2, 'Dadar Gulung', 'Resep Dadar Gulung khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+dadar+gulung\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung terigu, santan, telur, air daun suji, dan garam.\n2. Aduk hingga licin, saring.\n3. Buat kulit dadar tipis di wajan anti lengket.\n4. Campur kelapa parut dengan gula merah sisir untuk isian.\n5. Kukus isian kelapa sebentar hingga gula larut.\n6. Ambil selembar kulit, isi dengan campuran kelapa.\n7. Gulung rapat seperti amplop.\n8. Sajikan dadar gulung selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(539, 5, 2, 'Putu Ayu', 'Resep Putu Ayu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+putu+ayu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kocok telur dan gula pasir hingga mengembang putih.\n2. Masukkan tepung terigu dan maizena bergantian dengan santan.\n3. Tambahkan pasta pandan dan vanilla bubuk, aduk rata.\n4. Oles cetakan dengan minyak, taburi kelapa parut di dasar.\n5. Tuang adonan ke cetakan hingga penuh.\n6. Kukus dalam dandang panas selama 15 menit.\n7. Angkat dan keluarkan dari cetakan.\n8. Sajikan putu ayu selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(540, 6, 2, 'Nagasari', 'Resep Nagasari khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+nagasari\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung beras, gula pasir, garam, dan santan.\n2. Masak hingga mengental sambil diaduk, angkat.\n3. Potong pisang menjadi beberapa bagian.\n4. Ambil daun pisang, oles dengan minyak.\n5. Letakkan adonan tepung di daun, tambahkan pisang.\n6. Bungkus rapi seperti lontong.\n7. Kukus selama 20 menit hingga matang.\n8. Sajikan nagasari selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(541, 7, 2, 'Lemang', 'Resep Lemang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lemang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Cuci beras ketan, rendam semalaman.\n2. Campur ketan dengan santan dan garam, aduk rata.\n3. Siapkan potongan bambu, lapisi dalamnya dengan daun pisang.\n4. Masukkan campuran ketan ke dalam bambu.\n5. Panggang di atas bara api sambil diputar.\n6. Masak hingga ketan matang dan harum.\n7. Keluarkan lemang dari bambu.\n8. Potong dan sajikan dengan rendang atau serundeng.\n', 1, NULL, '2026-07-13 15:21:42'),
(542, 8, 2, 'Wajik', 'Resep Wajik khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+wajik\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kukus beras ketan hingga setengah matang.\n2. Rebus gula merah dengan santan, daun pandan, dan garam.\n3. Masak hingga gula larut dan mengental.\n4. Masukkan ketan kukus ke dalam kuah gula.\n5. Aduk rata, masak dengan api kecil hingga meresap.\n6. Angkat dan tuang ke loyang yang dioles minyak.\n7. Ratakan dan tekan-tekan hingga padat.\n8. Potong setelah dingin, sajikan.\n', 1, NULL, '2026-07-13 15:21:42'),
(543, 4, 2, 'Dodol', 'Resep Dodol khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+dodol\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung ketan dengan santan, aduk rata.\n2. Masukkan gula merah sisir dan garam.\n3. Masak dengan api kecil sambil terus diaduk.\n4. Tambahkan daun pandan.\n5. Aduk terus hingga adonan mengental dan tidak lengket.\n6. Proses ini memakan waktu 1-2 jam.\n7. Tuang ke loyang yang dioles minyak, ratakan.\n8. Potong setelah dingin dan set.\n', 1, NULL, '2026-07-13 15:21:42'),
(544, 5, 2, 'Wingko Babat', 'Resep Wingko Babat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+wingko+babat\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung ketan, kelapa parut, gula pasir, dan garam.\n2. Tuang santan sedikit demi sedikit, aduk rata.\n3. Tambahkan vanilla bubuk, uleni hingga bisa dibentuk.\n4. Panaskan wajan anti lengket dengan sedikit minyak.\n5. Cetak adonan bulat pipih, panggang dengan api kecil.\n6. Balik sekali hingga kedua sisi kecoklatan.\n7. Angkat dan sajikan.\n8. Wingko babat khas Semarang siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(545, 6, 2, 'Serabi', 'Resep Serabi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+serabi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung beras, gula pasir, garam, dan santan.\n2. Kocok telur, masukkan ke adonan, aduk rata.\n3. Diamkan adonan selama 30 menit.\n4. Panaskan cetakan serabi, oles dengan minyak.\n5. Tuang adonan ke cetakan, jangan penuh.\n6. Tutup dan masak dengan api kecil hingga matang.\n7. Angkat dan sajikan hangat.\n8. Serabi nikmat disantap dengan kuah kinca gula merah.\n', 1, NULL, '2026-07-13 15:21:42'),
(546, 7, 2, 'Kue Putu', 'Resep Kue Putu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+putu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung beras dengan garam, basahi sedikit air.\n2. Ayak tepung hingga butiran halus.\n3. Siapkan cetakan kue putu bambu.\n4. Isi setengah cetakan dengan tepung beras.\n5. Tambahkan potongan gula merah di tengah.\n6. Tutup dengan tepung beras lagi hingga penuh.\n7. Kukus dalam dandang panas selama 10 menit.\n8. Keluarkan dari cetakan, sajikan dengan kelapa parut.\n', 1, NULL, '2026-07-13 15:21:42'),
(547, 8, 4, 'Es Teh Manis', 'Resep Es Teh Manis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+teh+manis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus air hingga mendidih.\n2. Seduh teh dalam gelas dengan air panas.\n3. Tambahkan gula pasir, aduk hingga larut.\n4. Diamkan hingga suhu ruang.\n5. Siapkan gelas berisi es batu.\n6. Tuang teh manis ke dalam gelas.\n7. Sajikan es teh manis selagi dingin.\n8. Tambahkan irisan lemon jika suka.\n', 1, NULL, '2026-07-13 15:21:42'),
(548, 4, 4, 'Es Jeruk', 'Resep Es Jeruk khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+jeruk\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Peras jeruk manis, ambil airnya.\n2. Campur air perasan jeruk dengan gula pasir.\n3. Aduk hingga gula larut.\n4. Tambahkan air dan es batu.\n5. Aduk rata.\n6. Sajikan es jeruk segar.\n7. Hias dengan irisan jeruk di pinggir gelas.\n', 1, NULL, '2026-07-13 15:21:42'),
(549, 5, 4, 'Es Kopi Susu', 'Resep Es Kopi Susu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+kopi+susu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Seduh kopi bubuk dengan air panas.\n2. Tambahkan susu kental manis, aduk rata.\n3. Diamkan hingga suhu ruang.\n4. Siapkan gelas berisi es batu.\n5. Tuang kopi susu ke dalam gelas.\n6. Aduk rata sebelum dinikmati.\n7. Es kopi susu siap disajikan.\n', 1, NULL, '2026-07-13 15:21:42'),
(550, 6, 4, 'Es Cincau', 'Resep Es Cincau khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+cincau\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong cincau kotak-kotak kecil.\n2. Masukkan ke dalam gelas saji.\n3. Tambahkan es batu.\n4. Siram dengan sirup dan susu kental manis.\n5. Tambahkan air matang.\n6. Aduk rata sebelum dinikmati.\n7. Es cincau segar siap disajikan.\n', 1, NULL, '2026-07-13 15:21:42'),
(551, 7, 4, 'Es Kelapa Muda', 'Resep Es Kelapa Muda khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+kelapa+muda\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Siapkan air kelapa muda dan daging kelapa.\n2. Potong daging kelapa muda kecil-kecil.\n3. Masukkan ke gelas saji.\n4. Tambahkan es batu.\n5. Siram dengan sirup merah.\n6. Tuang air kelapa muda.\n7. Aduk rata, sajikan selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(552, 8, 4, 'Es Soda Gembira', 'Resep Es Soda Gembira khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+soda+gembira\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Siapkan gelas saji berisi es batu.\n2. Tuang sirup merah ke dalam gelas.\n3. Tambahkan susu kental manis.\n4. Tuang air soda perlahan.\n5. Aduk rata sebelum dinikmati.\n6. Es soda gembira siap disajikan.\n', 1, NULL, '2026-07-13 15:21:42'),
(553, 4, 4, 'Es Krim Soda', 'Resep Es Krim Soda khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+krim+soda\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Siapkan gelas saji berisi es batu.\n2. Tuang susu kental manis.\n3. Tuang air soda perlahan.\n4. Letakkan satu scoop es krim di atasnya.\n5. Sajikan segera selagi es krim belum meleleh.\n6. Es krim soda siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(554, 5, 4, 'Es Campur Soda', 'Resep Es Campur Soda khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+campur+soda\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rendam selasih dalam air hingga mengembang.\n2. Siapkan gelas saji berisi es batu.\n3. Masukkan selasih ke dalam gelas.\n4. Tuang sirup dan susu kental manis.\n5. Tuang air soda perlahan.\n6. Aduk rata, sajikan selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(555, 6, 4, 'Es Tebu', 'Resep Es Tebu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+tebu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Siapkan sari tebu segar.\n2. Siapkan gelas berisi es batu.\n3. Tuang sari tebu ke dalam gelas.\n4. Kucuri dengan jeruk nipis.\n5. Aduk rata.\n6. Sajikan es tebu selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(556, 7, 4, 'Es Selasih', 'Resep Es Selasih khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+selasih\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rendam selasih dalam air hingga mengembang.\n2. Siapkan gelas saji.\n3. Masukkan selasih ke dalam gelas.\n4. Tambahkan es batu.\n5. Siram dengan sirup dan susu kental manis.\n6. Tuang air matang, aduk rata.\n7. Sajikan es selasih selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42');
INSERT INTO `resep` (`id`, `id_user`, `id_kategori`, `judul`, `deskripsi`, `langkah_memasak`, `jumlah_porsi`, `foto`, `created_at`) VALUES
(557, 8, 4, 'Es Sirup', 'Resep Es Sirup khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+sirup\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Siapkan gelas saji.\n2. Tuang sirup ke dalam gelas.\n3. Tambahkan es batu.\n4. Tuang air matang.\n5. Aduk rata.\n6. Sajikan es sirup selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(558, 4, 4, 'Es Lemon Tea', 'Resep Es Lemon Tea khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+lemon+tea\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Seduh teh dengan air panas.\n2. Tambahkan gula pasir, aduk hingga larut.\n3. Diamkan hingga suhu ruang.\n4. Peras jeruk nipis, ambil airnya.\n5. Campur air jeruk nipis ke dalam teh.\n6. Siapkan gelas berisi es batu.\n7. Tuang lemon tea ke dalam gelas.\n8. Sajikan selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(559, 5, 4, 'Es Susu Coklat', 'Resep Es Susu Coklat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+susu+coklat\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur susu sapi, coklat bubuk, dan gula pasir.\n2. Aduk rata hingga coklat larut.\n3. Siapkan gelas berisi es batu.\n4. Tuang susu coklat ke dalam gelas.\n5. Aduk rata.\n6. Sajikan es susu coklat selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(560, 6, 4, 'Es Yogurt', 'Resep Es Yogurt khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+yogurt\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong stroberi kecil-kecil.\n2. Campur yogurt dengan susu kental manis.\n3. Siapkan gelas saji.\n4. Masukkan potongan stroberi.\n5. Tuang campuran yogurt.\n6. Tambahkan es batu.\n7. Sajikan es yogurt selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(561, 7, 4, 'Es Nata De Coco', 'Resep Es Nata De Coco khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+nata+de+coco\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong nata de coco kotak-kotak kecil.\n2. Masukkan ke dalam gelas saji.\n3. Tambahkan es batu.\n4. Tuang sirup dan susu kental manis.\n5. Tambahkan air matang.\n6. Aduk rata, sajikan selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(562, 8, 4, 'Wedang Jahe', 'Resep Wedang Jahe khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+wedang+jahe\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas jahe, memarkan atau iris tipis.\n2. Rebus air bersama jahe dan sereh geprek.\n3. Tambahkan gula merah.\n4. Rebus hingga mendidih dan harum.\n5. Saring ke dalam gelas atau cangkir.\n6. Sajikan wedang jahe selagi hangat.\n7. Wedang jahe cocok dinikmati saat cuaca dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(563, 4, 4, 'Wedang Uwuh', 'Resep Wedang Uwuh khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+wedang+uwuh\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas jahe, memarkan atau iris.\n2. Rebus air dengan jahe, kayu manis, cengkeh, dan pala.\n3. Tambahkan gula merah.\n4. Rebus hingga mendidih dan rempah meresap.\n5. Saring ke dalam cangkir.\n6. Sajikan wedang uwuh selagi hangat.\n7. Wedang uwuh khas Jogja siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(564, 5, 4, 'Wedang Ronde', 'Resep Wedang Ronde khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+wedang+ronde\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat isian: haluskan kacang tanah goreng dengan gula merah.\n2. Campur tepung ketan dengan air hangat, uleni hingga kalis.\n3. Pipihkan adonan, isi dengan kacang manis, bulatkan.\n4. Rebus ronde dalam air mendidih hingga mengapung.\n5. Rebus jahe dengan gula pasir hingga harum untuk kuah.\n6. Siapkan mangkuk, masukkan ronde.\n7. Tuang kuah jahe dan sedikit santan.\n8. Sajikan wedang ronde selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(565, 6, 4, 'Bajigur', 'Resep Bajigur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+bajigur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas jahe, memarkan.\n2. Rebus santan, gula merah, kopi, jahe, dan daun pandan.\n3. Tambahkan garam.\n4. Masak dengan api kecil hingga mendidih sambil diaduk.\n5. Saring ke dalam gelas atau cangkir.\n6. Sajikan bajigur selagi hangat.\n7. Bajigur khas Sunda siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(566, 7, 4, 'Bandrek', 'Resep Bandrek khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+bandrek\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas jahe, memarkan.\n2. Rebus air dengan jahe, kayu manis, dan cengkeh.\n3. Tambahkan gula merah dan santan.\n4. Masak hingga mendidih sambil diaduk.\n5. Saring ke dalam gelas saji.\n6. Sajikan bandrek selagi hangat.\n7. Bandrek khas Sunda siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(567, 8, 4, 'Sekoteng', 'Resep Sekoteng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sekoteng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus jahe dengan gula pasir hingga harum.\n2. Seduh mie bihun dengan air panas hingga lunak.\n3. Rebus kacang tanah hingga empuk.\n4. Siapkan mangkuk saji.\n5. Masukkan bihun, kacang tanah, dan potongan kol.\n6. Tuang kuah jahe panas.\n7. Sajikan sekoteng selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(568, 4, 4, 'Bir Pletok', 'Resep Bir Pletok khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+bir+pletok\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas jahe, memarkan.\n2. Rebus air dengan jahe, sereh, dan kayu manis.\n3. Tambahkan gula pasir.\n4. Rebus hingga mendidih dan harum.\n5. Angkat, saring, beri pewarna merah.\n6. Dinginkan dalam kulkas.\n7. Sajikan bir pletok dingin.\n8. Bir pletok khas Betawi siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(569, 5, 4, 'Teh Tarik', 'Resep Teh Tarik khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+teh+tarik\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Seduh teh dengan air panas, biarkan 3 menit.\n2. Saring teh ke dalam gelas lain.\n3. Tambahkan susu kental manis.\n4. Tarik teh dengan menuangkan dari tinggi ke rendah.\n5. Ulangi beberapa kali hingga berbusa.\n6. Sajikan teh tarik selagi hangat.\n7. Teh tarik khas Melayu siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(570, 6, 4, 'Kopi Tubruk', 'Resep Kopi Tubruk khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kopi+tubruk\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Masukkan kopi bubuk dan gula pasir ke dalam gelas.\n2. Didihkan air.\n3. Tuang air panas ke dalam gelas.\n4. Aduk rata hingga gula larut.\n5. Diamkan sebentar hingga ampas kopi mengendap.\n6. Sajikan kopi tubruk selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(571, 7, 4, 'Kopi Jahe', 'Resep Kopi Jahe khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kopi+jahe\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas jahe, memarkan atau iris tipis.\n2. Rebus air dengan jahe hingga mendidih.\n3. Masukkan kopi bubuk dan gula merah.\n4. Aduk rata, angkat.\n5. Saring ke dalam cangkir.\n6. Sajikan kopi jahe selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(572, 8, 4, 'Jus Alpukat', 'Resep Jus Alpukat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+alpukat\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Belah alpukat, ambil dagingnya.\n2. Masukkan alpukat, susu kental manis, es batu, dan air ke blender.\n3. Blender hingga halus dan tercampur rata.\n4. Tuang ke gelas saji.\n5. Sajikan jus alpukat selagi dingin.\n6. Tambahkan topping coklat atau keju jika suka.\n', 1, NULL, '2026-07-13 15:21:42'),
(573, 4, 4, 'Jus Mangga', 'Resep Jus Mangga khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+mangga\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas mangga, potong dagingnya.\n2. Masukkan mangga, gula pasir, es batu, dan air ke blender.\n3. Blender hingga halus.\n4. Tuang ke gelas saji.\n5. Sajikan jus mangga selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(574, 5, 4, 'Jus Jambu', 'Resep Jus Jambu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+jambu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong jambu biji, buang bijinya.\n2. Masukkan jambu, gula pasir, es batu, dan air ke blender.\n3. Blender hingga halus.\n4. Saring jika suka tekstur lembut.\n5. Tuang ke gelas saji.\n6. Sajikan jus jambu selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(575, 6, 4, 'Jus Tomat', 'Resep Jus Tomat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+tomat\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tomat, buang bijinya.\n2. Masukkan tomat, gula pasir, es batu, dan air ke blender.\n3. Blender hingga halus.\n4. Kucuri jeruk nipis, aduk rata.\n5. Tuang ke gelas saji.\n6. Sajikan jus tomat selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(576, 7, 4, 'Jus Wortel', 'Resep Jus Wortel khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+wortel\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas wortel, potong kecil-kecil.\n2. Masukkan wortel, susu sapi, gula pasir, dan es batu ke blender.\n3. Blender hingga halus.\n4. Saring jika perlu.\n5. Tuang ke gelas saji.\n6. Sajikan jus wortel selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(577, 8, 4, 'Jus Sirsak', 'Resep Jus Sirsak khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+sirsak\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas sirsak, ambil daging buahnya.\n2. Masukkan daging sirsak, susu kental manis, es batu, dan air ke blender.\n3. Blender hingga halus.\n4. Saring untuk memisahkan biji.\n5. Tuang ke gelas saji.\n6. Sajikan jus sirsak selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(578, 4, 4, 'Jus Strawberry', 'Resep Jus Strawberry khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+strawberry\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan stroberi, buang tangkainya.\n2. Masukkan stroberi, gula pasir, yogurt, dan es batu ke blender.\n3. Blender hingga halus.\n4. Tuang ke gelas saji.\n5. Sajikan jus strawberry selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(579, 5, 4, 'Jus Melon', 'Resep Jus Melon khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+melon\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas melon, potong dagingnya.\n2. Masukkan melon, gula pasir, es batu, dan air ke blender.\n3. Blender hingga halus.\n4. Tuang ke gelas saji.\n5. Sajikan jus melon selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(580, 6, 4, 'Jus Semangka', 'Resep Jus Semangka khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+jus+semangka\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong semangka, buang bijinya.\n2. Masukkan semangka, gula pasir, dan es batu ke blender.\n3. Blender hingga halus.\n4. Saring jika suka tekstur lembut.\n5. Tuang ke gelas saji.\n6. Sajikan jus semangka selagi dingin.\n', 1, NULL, '2026-07-13 15:21:42'),
(581, 7, 4, 'Es Kopyor', 'Resep Es Kopyor khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+es+kopyor\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Keruk daging kelapa muda memanjang seperti kopyor.\n2. Siapkan gelas saji.\n3. Masukkan kerukan kelapa.\n4. Tambahkan es batu.\n5. Tuang air kelapa, sirup, dan susu kental manis.\n6. Aduk rata, sajikan selagi dingin.\n7. Es kopyor siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:42'),
(582, 8, 5, 'Bakwan Jagung', 'Resep Bakwan Jagung khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+bakwan+jagung\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Serut jagung manis dari bonggolnya.\n2. Campur jagung dengan tepung terigu, telur, dan bawang putih halus.\n3. Tambahkan daun bawang iris, garam, dan merica.\n4. Aduk rata hingga adonan kental.\n5. Panaskan minyak dalam wajan.\n6. Sendok adonan ke minyak panas, goreng hingga kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan bakwan jagung selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(583, 4, 5, 'Bakwan Sayur', 'Resep Bakwan Sayur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+bakwan+sayur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Iris wortel dan kol tipis-tipis.\n2. Campur tepung terigu dengan air, bawang putih halus, garam, dan merica.\n3. Masukkan sayuran dan daun bawang, aduk rata.\n4. Panaskan minyak dalam wajan.\n5. Sendok adonan ke minyak panas.\n6. Goreng hingga kuning kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan bakwan sayur hangat dengan cabai rawit.\n', 1, NULL, '2026-07-13 15:21:42'),
(584, 5, 5, 'Combro', 'Resep Combro khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+combro\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas singkong, parut halus, peras airnya.\n2. Tumis oncom dengan cabai rawit dan daun bawang.\n3. Campur singkong parut dengan garam.\n4. Ambil adonan singkong, pipihkan.\n5. Isi dengan tumisan oncom, bentuk bulat lonjong.\n6. Goreng dalam minyak panas hingga kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan combro selagi hangat.\n', 1, NULL, '2026-07-13 15:21:42'),
(585, 6, 5, 'Misro', 'Resep Misro khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+misro\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas singkong, parut halus, peras airnya.\n2. Campur singkong parut dengan garam.\n3. Ambil adonan, pipihkan.\n4. Isi dengan potongan gula merah.\n5. Bentuk bulat lonjong.\n6. Goreng dalam minyak panas hingga kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan misro selagi hangat, gula di dalam akan meleleh.\n', 1, NULL, '2026-07-13 15:21:42'),
(586, 7, 5, 'Lemper', 'Resep Lemper khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lemper\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kukus beras ketan hingga setengah matang.\n2. Rebus santan dengan garam, tuang ke ketan, kukus lagi hingga matang.\n3. Tumis daging ayam cincang dengan bumbu hingga matang.\n4. Ambil ketan, pipihkan di atas daun pisang.\n5. Beri isian ayam cincang di tengah.\n6. Gulung dan padatkan.\n7. Potong-potong dan sajikan.\n8. Lemper siap dinikmati sebagai camilan.\n', 1, NULL, '2026-07-13 15:21:42'),
(587, 8, 5, 'Lontong Sayur', 'Resep Lontong Sayur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lontong+sayur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Cuci beras, masukkan ke dalam daun pisang bentuk silinder.\n2. Rebus lontong hingga matang, potong-potong.\n3. Potong labu siam kecil-kecil.\n4. Haluskan bawang merah, bawang putih, dan cabai merah.\n5. Tumis bumbu halus hingga harum.\n6. Masukkan labu siam dan santan, masak hingga matang.\n7. Sajikan lontong dengan sayur dan taburan bawang goreng.\n', 1, NULL, '2026-07-13 15:21:42'),
(588, 4, 5, 'Ketoprak', 'Resep Ketoprak khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ketoprak\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Seduh bihun dengan air panas hingga lunak, tiriskan.\n2. Goreng tahu hingga kecoklatan, potong dadu.\n3. Goreng kacang tanah, haluskan dengan cabai rawit dan gula merah.\n4. Campur bihun, tahu, dan toge.\n5. Siram dengan bumbu kacang dan kecap manis.\n6. Taburi daun bawang dan bawang goreng.\n7. Sajikan ketoprak dengan kerupuk.\n', 1, NULL, '2026-07-13 15:21:43'),
(589, 5, 5, 'Tahu Goreng', 'Resep Tahu Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih sesuai selera.\n2. Lumuri tahu dengan garam dan bawang putih halus.\n3. Diamkan 10 menit.\n4. Panaskan minyak.\n5. Goreng tahu hingga kecoklatan.\n6. Balik agar matang merata.\n7. Angkat dan tiriskan.\n8. Sajikan dengan cabai rawit hijau.\n', 1, NULL, '2026-07-13 15:21:43'),
(590, 6, 5, 'Tempe Goreng', 'Resep Tempe Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tempe+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tempe tipis-tipis.\n2. Haluskan bawang putih dan garam.\n3. Lumuri tempe dengan bumbu halus.\n4. Panaskan minyak.\n5. Goreng tempe hingga kecoklatan.\n6. Balik agar matang merata.\n7. Angkat dan tiriskan.\n8. Sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(591, 7, 5, 'Tahu Bulat', 'Resep Tahu Bulat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+bulat\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Hancurkan tahu putih hingga halus.\n2. Campur tahu dengan bawang putih halus, garam, dan merica.\n3. Tambahkan tepung terigu, aduk rata.\n4. Bentuk adonan bulat-bulat kecil.\n5. Panaskan minyak.\n6. Goreng tahu bulat hingga kuning kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan dengan cabai rawit atau saus sambal.\n', 1, NULL, '2026-07-13 15:21:43'),
(592, 8, 5, 'Cimol', 'Resep Cimol khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cimol\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung tapioka dan tepung terigu.\n2. Tambahkan daun bawang iris, garam, dan merica.\n3. Tuang air panas sedikit demi sedikit, uleni hingga kalis.\n4. Bentuk adonan bulat-bulat kecil.\n5. Panaskan minyak, goreng cimol hingga mengembang dan kecoklatan.\n6. Angkat dan tiriskan.\n7. Taburi dengan bumbu bubuk sesuai selera.\n8. Sajikan cimol selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(593, 4, 5, 'Cireng', 'Resep Cireng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+cireng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung tapioka dan tepung terigu.\n2. Tambahkan bawang putih halus, daun bawang, garam, dan merica.\n3. Tuang air panas, uleni hingga kalis.\n4. Bentuk adonan pipih bulat.\n5. Panaskan minyak.\n6. Goreng cireng hingga mengembang dan kecoklatan.\n7. Angkat dan tiriskan.\n8. Sajikan dengan bumbu rujak atau saus sambal.\n', 1, NULL, '2026-07-13 15:21:43'),
(594, 5, 5, 'Pisang Goreng Pasir', 'Resep Pisang Goreng Pasir khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+pisang+goreng+pasir\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas pisang, potong tipis memanjang.\n2. Campur tepung terigu, tepung beras, gula pasir, dan air.\n3. Celupkan pisang ke adonan tepung.\n4. Gulingkan di tepung kering (tepung pasir).\n5. Panaskan minyak.\n6. Goreng pisang hingga kuning keemasan.\n7. Angkat dan tiriskan.\n8. Sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(595, 6, 5, 'Singkong Keju', 'Resep Singkong Keju khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+singkong+keju\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas singkong, potong bentuk stik.\n2. Rebus singkong dengan bawang putih dan garam hingga empuk.\n3. Tiriskan dan dinginkan.\n4. Panaskan minyak.\n5. Goreng singkong hingga kuning kecoklatan.\n6. Angkat dan tiriskan.\n7. Taburi keju parut di atas singkong goreng.\n8. Sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(596, 7, 5, 'Ubi Cilembu', 'Resep Ubi Cilembu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+ubi+cilembu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Cuci bersih ubi cilembu, jangan dikupas.\n2. Panggang ubi dalam oven suhu 180 derajat selama 45 menit.\n3. Atau bakar di atas bara api hingga matang.\n4. Ubi akan mengeluarkan cairan manis seperti madu.\n5. Belah ubi, oles dengan margarin.\n6. Sajikan selagi hangat.\n7. Ubi cilembu khas Sumedang siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:43'),
(597, 8, 5, 'Kentang Goreng', 'Resep Kentang Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kentang+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas kentang, potong bentuk stik.\n2. Rendam dalam air garam selama 15 menit.\n3. Tiriskan dan keringkan.\n4. Panaskan minyak.\n5. Goreng kentang hingga kuning kecoklatan.\n6. Angkat dan tiriskan.\n7. Taburi garam dan bawang putih bubuk.\n8. Sajikan selagi hangat dengan saus sambal.\n', 1, NULL, '2026-07-13 15:21:43'),
(598, 4, 5, 'Macaroni Schotel', 'Resep Macaroni Schotel khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+macaroni+schotel\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus makaroni hingga empuk, tiriskan.\n2. Lelehkan margarin, tumis bawang putih cincang.\n3. Campur susu sapi, telur kocok, keju parut, garam, dan merica.\n4. Masukkan makaroni dan tumisan bawang ke campuran susu.\n5. Tuang ke loyang yang dioles margarin.\n6. Taburi keju parut di atasnya.\n7. Panggang dalam oven 180 derajat selama 30 menit.\n8. Potong dan sajikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(599, 5, 5, 'Martabak Telur', 'Resep Martabak Telur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+martabak+telur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung terigu dengan air dan garam, uleni hingga kalis.\n2. Gilas adonan tipis hingga tembus pandang.\n3. Kocok telur dengan daging cincang, daun bawang, garam, dan merica.\n4. Panaskan wajan dengan minyak.\n5. Masukkan kulit martabak, tuang isian telur di tengah.\n6. Lipat kulit ke tengah membentuk amplop.\n7. Goreng hingga kecoklatan, balik.\n8. Potong dan sajikan dengan acar.\n', 1, NULL, '2026-07-13 15:21:43'),
(600, 6, 5, 'Martabak Manis', 'Resep Martabak Manis khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+martabak+manis\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung terigu, telur, gula pasir, dan susu sapi.\n2. Aduk hingga licin, diamkan 15 menit.\n3. Panaskan cetakan martabak dengan margarin.\n4. Tuang adonan, putar agar menempel di tepi.\n5. Taburi gula pasir di atasnya, tutup hingga matang.\n6. Oles margarin, taburi coklat bubuk dan keju parut.\n7. Kucuri susu kental manis.\n8. Lipat dan potong, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(601, 7, 5, 'Roti Bakar', 'Resep Roti Bakar khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+roti+bakar\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Oles margarin di kedua sisi roti tawar.\n2. Panggang roti di teflon hingga kecoklatan.\n3. Balik roti agar matang merata.\n4. Angkat roti bakar.\n5. Oles coklat bubuk atau meses di atasnya.\n6. Taburi keju parut.\n7. Kucuri susu kental manis.\n8. Sajikan roti bakar selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(602, 8, 5, 'Roti Goreng', 'Resep Roti Goreng khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+roti+goreng\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Celupkan roti tawar ke kocokan telur.\n2. Pastikan roti terbalut telur merata.\n3. Panaskan minyak.\n4. Goreng roti sebentar hingga kecoklatan.\n5. Angkat dan tiriskan.\n6. Taburi gula pasir dan meses.\n7. Sajikan roti goreng selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(603, 4, 5, 'Sosis Solo', 'Resep Sosis Solo khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sosis+solo\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging ayam hingga empuk, cincang halus.\n2. Campur tepung terigu, telur, susu sapi, garam, dan merica.\n3. Masak adonan kulit di wajan anti lengket tipis-tipis.\n4. Campur daging ayam cincang dengan sisa adonan untuk isian.\n5. Ambil kulit, isi dengan adonan daging.\n6. Lipat amplop, goreng dalam minyak panas.\n7. Angkat dan tiriskan.\n8. Sajikan sosis solo dengan cabai rawit hijau.\n', 1, NULL, '2026-07-13 15:21:43'),
(604, 5, 5, 'Arem-arem', 'Resep Arem-arem khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+arem-arem\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Cuci beras, kukus setengah matang.\n2. Rebus santan dengan garam, tuang ke beras, aduk rata.\n3. Kukus kembali hingga matang.\n4. Tumis daging ayam cincang sebagai isian.\n5. Ambil adonan beras, pipihkan.\n6. Beri isian ayam, bulatkan lonjong.\n7. Bungkus dengan daun pisang, semat lidi.\n8. Kukus kembali 15 menit, sajikan.\n', 1, NULL, '2026-07-13 15:21:43'),
(605, 6, 5, 'Lontong Balap', 'Resep Lontong Balap khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lontong+balap\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Buat lontong dari beras yang dibungkus daun pisang, rebus hingga matang.\n2. Potong lontong kecil-kecil.\n3. Goreng tahu hingga kecoklatan, potong dadu.\n4. Seduh toge dengan air panas, tiriskan.\n5. Tata lontong, tahu, dan toge di piring.\n6. Siram dengan kecap manis.\n7. Taburi bawang goreng dan kerupuk.\n8. Sajikan lontong balap selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(606, 7, 5, 'Tahu Isi', 'Resep Tahu Isi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+isi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Belah tahu putih segitiga, goreng sebentar, kerok isinya.\n2. Campur tahu yang dikerok dengan toge, wortel serut, dan daun bawang.\n3. Tumis bawang putih, masukkan campuran sayur, beri garam.\n4. Isi tahu dengan tumisan sayur.\n5. Buat adonan tepung dari tepung terigu dan air.\n6. Celupkan tahu isi ke adonan tepung.\n7. Goreng dalam minyak panas hingga kecoklatan.\n8. Angkat dan sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(607, 8, 5, 'Tahu Aci', 'Resep Tahu Aci khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+tahu+aci\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih segitiga, goreng setengah matang.\n2. Belah tahu, ambil sebagian isinya.\n3. Campur tahu yang diambil dengan tepung tapioka, daun bawang, bawang putih, garam.\n4. Isi adonan tahu aci ke dalam tahu.\n5. Kukus sebentar hingga isian set.\n6. Panaskan minyak.\n7. Goreng tahu aci hingga kecoklatan.\n8. Sajikan dengan cabai rawit atau saus sambal.\n', 1, NULL, '2026-07-13 15:21:43'),
(608, 4, 5, 'Siomay', 'Resep Siomay khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+siomay\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kukus labu siam hingga empuk, haluskan.\n2. Campur ikan tuna halus dengan labu siam, tapioka, telur, bawang, daun bawang.\n3. Bentuk adonan bulat lonjong.\n4. Kukus siomay selama 20 menit hingga matang.\n5. Haluskan kacang tanah goreng dengan cabai dan gula merah.\n6. Potong siomay, siram dengan bumbu kacang.\n7. Tambahkan kecap manis dan sambal.\n8. Sajikan siomay dengan tahu goreng dan lontong.\n', 1, NULL, '2026-07-13 15:21:43'),
(609, 5, 5, 'Lemper Ayam', 'Resep Lemper Ayam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+lemper+ayam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kukus beras ketan hingga setengah matang.\n2. Rebus santan dengan garam, campur ke ketan, kukus lagi hingga matang.\n3. Suwir daging ayam, tumis dengan bumbu hingga kering.\n4. Ambil ketan, pipihkan di atas daun pisang.\n5. Beri isian ayam suwir di tengah.\n6. Gulung dan padatkan silinder panjang.\n7. Potong-potong dan bungkus lagi dengan daun pisang.\n8. Sajikan lemper ayam sebagai camilan.\n', 1, NULL, '2026-07-13 15:21:43'),
(610, 6, 5, 'Kue Lumpur', 'Resep Kue Lumpur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+lumpur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kocok telur dan gula pasir hingga mengembang.\n2. Masukkan tepung terigu bergantian dengan susu sapi.\n3. Tambahkan margarin cair dan vanilla bubuk.\n4. Panaskan cetakan kue lumpur, oles margarin.\n5. Tuang adonan ke cetakan hampir penuh.\n6. Taburi kismis di atasnya.\n7. Tutup dan masak dengan api kecil hingga matang.\n8. Angkat dan sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(611, 7, 5, 'Kue Bawang', 'Resep Kue Bawang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kue+bawang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Campur tepung terigu, tepung tapioka, dan garam.\n2. Haluskan bawang merah dan bawang putih, campur ke adonan.\n3. Tambahkan telur dan daun bawang iris, uleni hingga kalis.\n4. Gilas adonan tipis, potong kecil-kecil.\n5. Panaskan minyak.\n6. Goreng adonan hingga kuning kecoklatan.\n7. Angkat dan tiriskan.\n8. Simpan dalam toples kedap udara.\n', 1, NULL, '2026-07-13 15:21:43'),
(612, 8, 5, 'Stik Keju', 'Resep Stik Keju khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+stik+keju\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Parut keju cheddar halus.\n2. Campur tepung terigu, keju parut, margarin, telur, dan garam.\n3. Uleni hingga kalis.\n4. Gilas adonan tipis, potong memanjang seperti stik.\n5. Tata di loyang yang dioles margarin.\n6. Panggang dalam oven suhu 160 derajat selama 20 menit.\n7. Angkat dan dinginkan.\n8. Simpan dalam toples kedap udara.\n', 1, NULL, '2026-07-13 15:21:43'),
(613, 4, 5, 'Putri Salju', 'Resep Putri Salju khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+putri+salju\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kocok margarin dengan gula halus hingga lembut.\n2. Masukkan tepung terigu dan keju parut, aduk rata.\n3. Uleni hingga bisa dibentuk.\n4. Bentuk adonan bulan sabit atau sesuai selera.\n5. Tata di loyang, panggang oven 150 derajat selama 25 menit.\n6. Angkat dan dinginkan.\n7. Taburi gula halus di atasnya.\n8. Simpan dalam toples kedap udara.\n', 1, NULL, '2026-07-13 15:21:43'),
(614, 5, 5, 'Kastengel', 'Resep Kastengel khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+kastengel\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Parut keju cheddar, sisihkan sebagian untuk taburan.\n2. Kocok margarin dan telur hingga tercampur.\n3. Masukkan tepung terigu, keju parut, dan garam.\n4. Uleni hingga kalis, gilas tipis.\n5. Potong bentuk persegi panjang atau batang.\n6. Oles dengan kuning telur, taburi keju parut.\n7. Panggang oven 150 derajat selama 20 menit.\n8. Dinginkan dan simpan dalam toples.\n', 1, NULL, '2026-07-13 15:21:43'),
(615, 6, 6, 'Soto Ayam Lamongan', 'Resep Soto Ayam Lamongan khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+ayam+lamongan\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus ayam hingga empuk, angkat dan suwir-suwir.\n2. Haluskan bawang putih, kunyit, jahe, dan garam.\n3. Tumis bumbu halus hingga harum, masukkan daun salam dan sereh.\n4. Tuang kaldu ayam, masak hingga mendidih.\n5. Siapkan mangkuk saji, isi nasi, toge, dan suwiran ayam.\n6. Siram dengan kuah soto panas.\n7. Taburi bawang goreng dan daun bawang.\n8. Sajikan dengan telur rebus dan sambal.\n', 1, NULL, '2026-07-13 15:21:43'),
(616, 7, 6, 'Soto Daging Sapi', 'Resep Soto Daging Sapi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+daging+sapi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging sapi hingga empuk, potong dadu.\n2. Haluskan bawang putih, kunyit, jahe, dan garam.\n3. Tumis bumbu halus, masukkan daun salam dan sereh.\n4. Tuang air kaldu daging, masak hingga mendidih.\n5. Siapkan mangkuk, isi nasi, toge, dan potongan daging.\n6. Siram dengan kuah soto panas.\n7. Taburi daun bawang dan bawang goreng.\n8. Sajikan dengan sambal dan jeruk nipis.\n', 1, NULL, '2026-07-13 15:21:43'),
(617, 8, 6, 'Soto Kudus', 'Resep Soto Kudus khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+kudus\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus ayam hingga empuk, suwir-suwir.\n2. Haluskan bawang putih, kemiri, jahe, dan garam.\n3. Tumis bumbu halus, masukkan daun salam dan sereh.\n4. Tuang kaldu ayam, biarkan mendidih.\n5. Siapkan mangkuk, isi nasi, suwiran ayam, dan daun bawang.\n6. Siram kuah soto panas.\n7. Taburi bawang goreng.\n8. Sajikan dengan sambal dan krupuk.\n', 1, NULL, '2026-07-13 15:21:43'),
(618, 4, 6, 'Soto Padang', 'Resep Soto Padang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+padang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging sapi hingga empuk, iris tipis.\n2. Goreng kentang iris tipis untuk keripik kentang.\n3. Haluskan bawang putih, kunyit, jahe, dan garam.\n4. Tumis bumbu halus dengan sereh dan daun salam.\n5. Tuang air kaldu daging, masak hingga mendidih.\n6. Siapkan mangkuk, isi nasi, irisan daging, dan keripik kentang.\n7. Siram kuah soto panas.\n8. Sajikan dengan sambal dan perasan jeruk nipis.\n', 1, NULL, '2026-07-13 15:21:43'),
(619, 5, 6, 'Soto Sulung', 'Resep Soto Sulung khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+sulung\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus ayam dengan air hingga empuk, suwir-suwir.\n2. Haluskan bawang putih, kunyit, kemiri, jahe, dan garam.\n3. Tumis bumbu halus, masukkan daun salam.\n4. Tuang kaldu ayam dan santan.\n5. Masak hingga mendidih sambil diaduk.\n6. Siapkan mangkuk, isi nasi dan suwiran ayam.\n7. Siram kuah soto, taburi daun bawang dan bawang goreng.\n8. Sajikan hangat dengan sambal.\n', 1, NULL, '2026-07-13 15:21:43'),
(620, 6, 6, 'Soto Pekalongan', 'Resep Soto Pekalongan khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+pekalongan\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus ayam hingga empuk, suwir-suwir.\n2. Goreng tempe, potong dadu.\n3. Haluskan bawang putih, kunyit, kemiri, dan garam.\n4. Tumis bumbu halus, masukkan daun salam.\n5. Tuang kaldu ayam dan santan, aduk rata.\n6. Masak hingga mendidih.\n7. Siapkan mangkuk, isi nasi, suwiran ayam, dan tempe.\n8. Siram kuah soto, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(621, 7, 6, 'Soto Ambengan', 'Resep Soto Ambengan khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+ambengan\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus ayam hingga empuk, goreng sebentar, suwir-suwir.\n2. Haluskan bawang putih, kunyit, jahe, kemiri, dan garam.\n3. Tumis bumbu halus, masukkan daun salam.\n4. Tuang kaldu ayam, masak hingga mendidih.\n5. Siapkan mangkuk, isi nasi, toge, dan suwiran ayam.\n6. Siram kuah soto panas.\n7. Taburi daun bawang dan bawang goreng.\n8. Sajikan dengan sambal dan krupuk.\n', 1, NULL, '2026-07-13 15:21:43'),
(622, 8, 6, 'Soto Tangkar', 'Resep Soto Tangkar khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+soto+tangkar\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging iga sapi hingga empuk.\n2. Potong kentang dadu, goreng.\n3. Haluskan bawang putih, kemiri, jahe, dan garam.\n4. Tumis bumbu halus, masukkan daun salam.\n5. Tuang kaldu dan santan, aduk rata.\n6. Masak hingga mendidih.\n7. Siapkan mangkuk, isi nasi, daging iga, dan kentang goreng.\n8. Siram kuah soto, sajikan dengan sambal.\n', 1, NULL, '2026-07-13 15:21:43'),
(623, 4, 6, 'Sup Ayam Bening', 'Resep Sup Ayam Bening khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+ayam+bening\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil, buang kulitnya.\n2. Iris wortel dan kentang dadu kecil.\n3. Didihkan air, masukkan ayam dan bawang putih geprek.\n4. Masak hingga ayam setengah matang.\n5. Masukkan wortel dan kentang.\n6. Tambahkan garam dan merica bubuk.\n7. Masak hingga sayuran empuk.\n8. Taburi daun bawang dan seledri, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(624, 5, 6, 'Sup Ayam Rempah', 'Resep Sup Ayam Rempah khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+ayam+rempah\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil, cuci bersih.\n2. Didihkan air, masukkan ayam, bawang putih, jahe, daun salam, dan sereh.\n3. Iris wortel dan kentang dadu.\n4. Masukkan sayuran ke dalam sup.\n5. Tambahkan garam dan merica.\n6. Masak hingga ayam dan sayuran empuk.\n7. Koreksi rasa.\n8. Sajikan sup ayam rempah selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(625, 6, 6, 'Sup Ayam Jahe', 'Resep Sup Ayam Jahe khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+ayam+jahe\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil.\n2. Iris jahe tipis-tipis.\n3. Didihkan air, masukkan ayam dan jahe.\n4. Tambahkan irisan wortel dan jamur sagu.\n5. Beri garam dan merica.\n6. Masak hingga ayam empuk dan kaldu harum.\n7. Taburi daun bawang.\n8. Sajikan sup ayam jahe selagi hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(626, 7, 6, 'Sup Ayam Sayur', 'Resep Sup Ayam Sayur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+ayam+sayur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong ayam kecil-kecil.\n2. Iris wortel, buncis, dan kol sesuai selera.\n3. Didihkan air, masukkan ayam dan bawang putih geprek.\n4. Masak hingga ayam empuk.\n5. Masukkan wortel dan buncis.\n6. Tambahkan kol, garam, dan merica.\n7. Masak hingga semua sayuran matang.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:43'),
(627, 8, 6, 'Sup Daging Sapi', 'Resep Sup Daging Sapi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+daging+sapi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong daging sapi dadu kecil.\n2. Didihkan air, masukkan daging sapi dan bawang putih geprek.\n3. Masak hingga daging empuk.\n4. Masukkan wortel dan kentang potong dadu.\n5. Tambahkan garam dan merica.\n6. Masak hingga sayuran empuk.\n7. Taburi daun bawang dan seledri.\n8. Sajikan sup daging sapi selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(628, 4, 6, 'Sup Kambing', 'Resep Sup Kambing khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+kambing\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong daging kambing dadu kecil.\n2. Didihkan air, masukkan daging kambing dan jahe geprek.\n3. Masak hingga daging empuk.\n4. Haluskan bawang putih, tumis hingga harum.\n5. Tuang tumisan ke dalam kuah sup.\n6. Tambahkan santan, susu sapi, tomat, garam, dan merica.\n7. Aduk rata, masak hingga mendidih.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(629, 5, 6, 'Sup Iga Sapi', 'Resep Sup Iga Sapi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+iga+sapi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus iga sapi hingga empuk, buang lemak berlebih.\n2. Potong wortel dan kentang dadu.\n3. Tumis bawang putih cincang hingga harum.\n4. Masukkan tumisan ke dalam rebusan iga.\n5. Tambahkan wortel dan kentang.\n6. Beri garam dan merica.\n7. Masak hingga sayuran empuk.\n8. Taburi daun bawang dan seledri, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(630, 6, 6, 'Sup Buntut', 'Resep Sup Buntut khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+buntut\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan buntut sapi, rebus hingga empuk.\n2. Potong wortel dan kentang dadu.\n3. Tumis bawang putih cincang hingga harum.\n4. Masukkan ke dalam kaldu buntut.\n5. Tambahkan wortel dan kentang.\n6. Beri garam dan merica.\n7. Masak hingga sayuran empuk.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(631, 7, 6, 'Sup Jagung Ayam', 'Resep Sup Jagung Ayam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+jagung+ayam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Serut jagung manis dari bonggolnya.\n2. Potong ayam dadu kecil.\n3. Didihkan air, masukkan ayam dan jagung.\n4. Tambahkan bawang putih geprek.\n5. Kocok telur, tuang perlahan sambil diaduk.\n6. Beri garam dan merica.\n7. Masak hingga matang.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(632, 8, 6, 'Sup Tomat', 'Resep Sup Tomat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+tomat\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tomat kecil-kecil.\n2. Potong ayam dadu kecil.\n3. Tumis bawang putih hingga harum.\n4. Masukkan tomat, masak hingga layu.\n5. Tuang air, masukkan ayam.\n6. Kocok telur, tuang perlahan sambil diaduk.\n7. Beri garam dan merica, masak hingga matang.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(633, 4, 6, 'Sup Brokoli', 'Resep Sup Brokoli khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+brokoli\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong wortel tipis.\n2. Potong ayam dadu kecil.\n3. Didihkan air, masukkan ayam dan bawang putih.\n4. Masukkan wortel.\n5. Beri garam dan merica.\n6. Masak hingga semua bahan empuk.\n7. Angkat dan sajikan hangat.\n8. Taburi bawang goreng jika suka.\n', 1, NULL, '2026-07-13 15:21:44'),
(634, 5, 6, 'Sup Sayur Bakso', 'Resep Sup Sayur Bakso khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+sayur+bakso\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong wortel dan kol sesuai selera.\n2. Didihkan air, masukkan bawang putih geprek.\n3. Masukkan wortel, masak hingga setengah matang.\n4. Masukkan bakso sapi, masak hingga mengapung.\n5. Tambahkan kol, garam, dan merica.\n6. Masak sebentar hingga kol layu.\n7. Taburi daun bawang.\n8. Sajikan sup sayur bakso selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(635, 6, 6, 'Sup Tahu', 'Resep Sup Tahu khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+tahu\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih dadu kecil.\n2. Potong ayam dadu kecil.\n3. Didihkan air, masukkan ayam dan bawang putih.\n4. Masak hingga ayam empuk.\n5. Masukkan tahu, garam, dan merica.\n6. Masak sebentar hingga tahu panas.\n7. Taburi daun bawang.\n8. Sajikan sup tahu selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(636, 7, 6, 'Sup Tahu Telur', 'Resep Sup Tahu Telur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+tahu+telur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih dadu kecil.\n2. Kocok telur lepas.\n3. Didihkan air, masukkan bawang putih geprek.\n4. Masukkan tahu, garam, dan merica.\n5. Tuang telur perlahan sambil diaduk.\n6. Masak hingga telur matang.\n7. Taburi daun bawang.\n8. Sajikan sup tahu telur selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(637, 8, 6, 'Sup Oyong', 'Resep Sup Oyong khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+oyong\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas oyong, potong bulat-bulat.\n2. Iris wortel tipis.\n3. Didihkan air, masukkan bawang putih geprek.\n4. Masukkan wortel, masak sebentar.\n5. Masukkan oyong, garam, dan merica.\n6. Masak sebentar saja hingga oyong layu.\n7. Angkat dan sajikan.\n8. Sup oyong ringan dan segar.\n', 1, NULL, '2026-07-13 15:21:44'),
(638, 4, 6, 'Sup Lobak', 'Resep Sup Lobak khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+lobak\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas lobak, potong tipis bulat.\n2. Potong ayam dadu kecil.\n3. Didihkan air, masukkan ayam dan bawang putih.\n4. Masak hingga ayam setengah matang.\n5. Masukkan lobak, garam, dan merica.\n6. Masak hingga lobak empuk dan transparan.\n7. Taburi daun bawang.\n8. Sajikan sup lobak selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(639, 5, 6, 'Sup Ikan', 'Resep Sup Ikan khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+ikan\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Bersihkan ikan nila, potong beberapa bagian.\n2. Lumuri ikan dengan jeruk nipis dan garam.\n3. Didihkan air, masukkan bawang putih geprek dan jahe.\n4. Masukkan ikan, masak dengan api kecil.\n5. Tambahkan garam dan merica.\n6. Masak hingga ikan matang.\n7. Taburi daun bawang dan seledri.\n8. Sajikan sup ikan selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(640, 6, 6, 'Sup Udang', 'Resep Sup Udang khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+udang\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas udang, buang kepala dan kulit.\n2. Iris wortel tipis.\n3. Didihkan air, masukkan bawang putih dan jahe geprek.\n4. Masukkan wortel, masak sebentar.\n5. Masukkan udang, garam, dan merica.\n6. Masak hingga udang berubah warna dan matang.\n7. Taburi daun bawang.\n8. Sajikan sup udang selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(641, 7, 6, 'Sup Oyong Bakso', 'Resep Sup Oyong Bakso khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+oyong+bakso\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas oyong, potong bulat.\n2. Iris wortel tipis, potong bakso jadi dua.\n3. Didihkan air, masukkan bawang putih geprek.\n4. Masukkan wortel dan bakso.\n5. Tambahkan garam dan merica.\n6. Masukkan oyong, masak sebentar.\n7. Angkat dan sajikan.\n8. Sup oyong bakso siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:44'),
(642, 8, 6, 'Sup Makaroni', 'Resep Sup Makaroni khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+makaroni\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus makaroni hingga empuk, tiriskan.\n2. Potong ayam dan wortel dadu kecil.\n3. Didihkan air, masukkan ayam dan bawang putih.\n4. Masukkan wortel dan makaroni.\n5. Beri garam dan merica.\n6. Masak hingga semua matang.\n7. Taburi daun bawang.\n8. Sajikan sup makaroni selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(643, 4, 6, 'Sup Kacang Merah', 'Resep Sup Kacang Merah khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+kacang+merah\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rendam kacang merah semalaman, rebus hingga empuk.\n2. Potong daging sapi dadu kecil.\n3. Didihkan air, masukkan daging dan bawang putih.\n4. Masak hingga daging empuk.\n5. Masukkan kacang merah dan wortel.\n6. Beri garam dan merica.\n7. Masak hingga wortel matang.\n8. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(644, 5, 6, 'Sup Kacang Hijau', 'Resep Sup Kacang Hijau khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+kacang+hijau\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rendam kacang hijau, rebus hingga pecah dan empuk.\n2. Kupas jahe, memarkan.\n3. Masukkan jahe dan garam ke dalam rebusan kacang hijau.\n4. Tambahkan gula merah, aduk rata.\n5. Masukkan santan, aduk perlahan.\n6. Masak hingga mendidih.\n7. Angkat dan sajikan hangat.\n8. Sup kacang hijau cocok untuk cuaca dingin.\n', 1, NULL, '2026-07-13 15:21:44'),
(645, 6, 6, 'Sayur Bening Bayam', 'Resep Sayur Bening Bayam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sayur+bening+bayam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Petik daun bayam, cuci bersih.\n2. Potong jagung manis kecil-kecil.\n3. Didihkan air, masukkan jagung dan bawang putih.\n4. Masak hingga jagung empuk.\n5. Masukkan bayam, aduk sebentar.\n6. Tambahkan garam dan gula pasir.\n7. Angkat segera, sajikan.\n8. Sayur bening bayam siap dinikmati.\n', 1, NULL, '2026-07-13 15:21:44');
INSERT INTO `resep` (`id`, `id_user`, `id_kategori`, `judul`, `deskripsi`, `langkah_memasak`, `jumlah_porsi`, `foto`, `created_at`) VALUES
(646, 7, 6, 'Sayur Bening Oyong', 'Resep Sayur Bening Oyong khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sayur+bening+oyong\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas oyong, potong bulat.\n2. Iris wortel tipis.\n3. Didihkan air, masukkan bawang putih dan wortel.\n4. Masukkan oyong, garam, dan gula.\n5. Masak sebentar hingga oyong layu.\n6. Angkat dan sajikan.\n7. Sayur bening oyong segar dan ringan.\n', 1, NULL, '2026-07-13 15:21:44'),
(647, 8, 6, 'Sayur Bayam Jagung', 'Resep Sayur Bayam Jagung khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sayur+bayam+jagung\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Petik bayam, cuci bersih.\n2. Potong jagung dan wortel kecil-kecil.\n3. Didihkan air, masukkan jagung dan wortel.\n4. Masak hingga empuk.\n5. Masukkan bayam, garam, dan gula.\n6. Aduk sebentar, angkat.\n7. Sajikan sayur bayam jagung selagi hangat.\n', 1, NULL, '2026-07-13 15:21:44'),
(648, 4, 6, 'Sop Ubi', 'Resep Sop Ubi khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sop+ubi\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Kupas singkong, potong dadu, goreng hingga kecoklatan.\n2. Potong daging sapi dadu kecil, rebus hingga empuk.\n3. Haluskan bawang putih, tumis hingga harum.\n4. Masukkan tumisan ke dalam rebusan daging.\n5. Tambahkan garam dan merica.\n6. Masukkan singkong goreng ke dalam sup.\n7. Taburi daun bawang, sajikan hangat.\n8. Sop ubi khas Makassar siap dinikmati.\n', 1, NULL, '2026-07-13 15:24:10'),
(649, 5, 6, 'Sop Konro', 'Resep Sop Konro khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sop+konro\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus iga sapi hingga empuk, buang lemak.\n2. Haluskan kluwek, bawang merah, bawang putih, kunyit, dan jahe.\n3. Tumis bumbu halus dengan sereh hingga harum.\n4. Masukkan tumisan ke dalam rebusan iga.\n5. Tambahkan garam, masak hingga bumbu meresap.\n6. Koreksi rasa, angkat.\n7. Sajikan sop konro dengan nasi hangat dan sambal.\n8. Sop konro khas Makassar siap dinikmati.\n', 1, NULL, '2026-07-13 15:24:10'),
(650, 6, 6, 'Coto Makassar', 'Resep Coto Makassar khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+coto+makassar\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging sapi hingga empuk, potong dadu.\n2. Sangrai kacang tanah, haluskan.\n3. Haluskan bawang merah, bawang putih, kunyit, dan jahe.\n4. Tumis bumbu halus dengan sereh hingga harum.\n5. Masukkan kacang tanah halus dan air kaldu.\n6. Masukkan daging, masak hingga mendidih.\n7. Koreksi rasa, sajikan dengan ketupat.\n8. Coto Makassar siap dinikmati.\n', 1, NULL, '2026-07-13 15:24:10'),
(651, 7, 6, 'Pallubasa', 'Resep Pallubasa khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+pallubasa\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Rebus daging sapi hingga empuk, potong dadu.\n2. Sangrai kelapa parut, haluskan.\n3. Haluskan bawang merah, bawang putih, kunyit, dan jahe.\n4. Tumis bumbu halus dengan sereh hingga harum.\n5. Masukkan kelapa sangrai halus dan air kaldu.\n6. Masukkan daging, masak hingga mendidih.\n7. Koreksi rasa, sajikan dengan nasi hangat.\n8. Pallubasa khas Makassar siap dinikmati.\n', 1, NULL, '2026-07-13 15:24:10'),
(652, 8, 6, 'Sup Krim Jagung', 'Resep Sup Krim Jagung khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+krim+jagung\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Serut jagung manis, blender setengah halus.\n2. Lelehkan margarin, tumis bawang putih cincang.\n3. Masukkan jagung blender dan susu sapi.\n4. Masak dengan api kecil sambil diaduk.\n5. Kocok telur, tuang perlahan sambil diaduk.\n6. Beri garam dan merica.\n7. Masak hingga mengental, sajikan hangat.\n', 1, NULL, '2026-07-13 15:24:10'),
(653, 4, 6, 'Sup Merah', 'Resep Sup Merah khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+merah\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Blender tomat hingga halus.\n2. Potong ayam dan wortel dadu kecil.\n3. Tumis bawang putih hingga harum.\n4. Masukkan tomat blender dan saus tomat.\n5. Tambahkan air, masukkan ayam dan wortel.\n6. Beri garam dan gula pasir.\n7. Masak hingga ayam empuk, sajikan hangat.\n', 1, NULL, '2026-07-13 15:24:10'),
(654, 5, 6, 'Sup Tahu Putih', 'Resep Sup Tahu Putih khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+tahu+putih\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Potong tahu putih dadu kecil.\n2. Potong ayam dadu kecil.\n3. Didihkan air, masukkan ayam dan bawang putih.\n4. Masak hingga ayam empuk.\n5. Masukkan tahu, garam, dan merica.\n6. Masak sebentar hingga tahu panas.\n7. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:24:10'),
(655, 6, 6, 'Sup Tomat Ayam', 'Resep Sup Tomat Ayam khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+tomat+ayam\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Blender tomat hingga halus.\n2. Potong ayam dadu kecil.\n3. Tumis bawang putih hingga harum.\n4. Masukkan tomat blender dan air.\n5. Masukkan ayam, masak hingga empuk.\n6. Kocok telur, tuang perlahan sambil diaduk.\n7. Beri garam dan merica, sajikan hangat.\n', 1, NULL, '2026-07-13 15:24:10'),
(656, 7, 6, 'Sup Jamur', 'Resep Sup Jamur khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', 'Sumber: https://www.google.com/search?q=resep+sup+jamur\nDiolah dari berbagai referensi resep Nusantara.\n\n1. Seduh jamur sagu dengan air panas hingga lunak, tiriskan.\n2. Potong ayam dadu kecil.\n3. Tumis bawang putih hingga harum.\n4. Masukkan ayam, masak hingga berubah warna.\n5. Tambahkan air, masak hingga ayam empuk.\n6. Masukkan jamur sagu, garam, dan merica.\n7. Taburi daun bawang, sajikan hangat.\n', 1, NULL, '2026-07-13 15:24:10');
