INSERT INTO `resep_pribadi` (`id`, `id_user`, `id_kategori`, `judul`, `deskripsi`, `langkah_memasak`, `jumlah_porsi`, `foto`, `sumber_id`, `created_at`) VALUES
(1, 10, 6, 'Soto Ayam Bening arka', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Siapkan semua bahan dan cuci bersih.\r\n2. Olah Soto Ayam Bening sesuai selera dengan bumbu yang sudah disiapkan.\r\n3. Rebus dalam air mendidih hingga matang dan empuk. Sajikan selagi hangat.', 1, NULL, NULL, '2026-07-13 14:26:35'),
(2, 10, 6, 'Soto Ayam Kuning (Modifikasi)', 'Resep lezat khas Nusantara. Cocok untuk hidangan sehari-hari keluarga.', '1. Haluskan bawang merah, bawang putih, kunyit, jahe, dan kemiri.\r\n2. Tumis bumbu halus hingga harum.\r\n3. Rebus ayam dengan air dan bumbu tumis.\r\n4. Angkat ayam, goreng sebentar, suwir-suwir.\r\n5. Tambahkan santan ke dalam kuah, aduk rata.\r\n6. Sajikan dengan suwiran ayam, kol iris, dan toge.\r\n7. Tambahkan sambal dan kecap manis.\r\n8. Soto ayam kuning siap dinikmati.\r\n\r\n\r\nSumber: https://www.google.com/search?q=resep+Soto+Ayam+Kuning', 1, NULL, 223, '2026-07-13 16:24:11'),
(4, 10, 2, 'nasi goreng albani', 'enak', 'masak', 1, NULL, NULL, '2026-07-14 08:21:36');
